{"command":"cd /workspace && rm -f main_tmp.go && cat > ansi.go <<'EOF'
package main

import (
	"strings"
	"unicode/utf8"

	"github.com/rivo/uniseg"
)

// skipEscape returns the length of the escape sequence starting at s[i]
// (s[i] must be ESC). It returns at least 1.
func skipEscape(s string, i int) int {
	n := len(s)
	j := i + 1
	if j >= n {
		return 1
	}
	switch s[j] {
	case '[':
		j++
		for j < n && s[j] >= 0x30 && s[j] <= 0x3f {
			j++
		}
		for j < n && s[j] >= 0x20 && s[j] <= 0x2f {
			j++
		}
		if j < n && s[j] >= 0x40 && s[j] <= 0x7e {
			j++
		}
		return j - i
	case ']', 'P', 'X', '^', '_':
		j++
		for j < n {
			if s[j] == 0x07 {
				j++
				break
			}
			if s[j] == 0x1b && j+1 < n && s[j+1] == '\\' {
				j += 2
				break
			}
			j++
		}
		return j - i
	default:
		for j < n && s[j] >= 0x20 && s[j] <= 0x2f {
			j++
		}
		if j < n && s[j] >= 0x30 && s[j] <= 0x7e {
			j++
		}
		return j - i
	}
}

// StringWidth returns the display width of s, ignoring ANSI escape codes.
func StringWidth(s string) int {
	w := 0
	for i := 0; i < len(s); {
		c := s[i]
		if c == 0x1b {
			i += skipEscape(s, i)
			continue
		}
		if c < 0x80 {
			if c >= 0x20 && c < 0x7f {
				w++
			}
			i++
			continue
		}
		cluster, _, cw, _ := uniseg.FirstGraphemeClusterInString(s[i:], -1)
		if len(cluster) == 0 {
			i++
			continue
		}
		w += cw
		i += len(cluster)
	}
	return w
}

// Truncate truncates s to the given display width, keeping ANSI sequences.
func Truncate(s string, length int) string {
	if StringWidth(s) <= length {
		return s
	}
	if length < 0 {
		return ""
	}
	var b strings.Builder
	cur := 0
	ignoring := false
	for i := 0; i < len(s); {
		c := s[i]
		if c == 0x1b {
			l := skipEscape(s, i)
			b.WriteString(s[i : i+l])
			i += l
			continue
		}
		if c < 0x80 {
			if c >= 0x20 && c < 0x7f {
				if cur >= length {
					ignoring = true
				}
				if ignoring {
					i++
					continue
				}
				cur++
				b.WriteByte(c)
				i++
				if cur > length {
					ignoring = true
				}
				continue
			}
			b.WriteByte(c)
			i++
			continue
		}
		cluster, _, cw, _ := uniseg.FirstGraphemeClusterInString(s[i:], -1)
		if len(cluster) == 0 {
			cluster = s[i : i+1]
			cw = 0
		}
		i += len(cluster)
		if ignoring {
			continue
		}
		if cur+cw > length {
			ignoring = true
			continue
		}
		cur += cw
		b.WriteString(cluster)
	}
	return b.String()
}

// truncateLeftRunes removes runes from the left until width <= w.
func truncateLeftRunes(s string, w int) string {
	for StringWidth(s) > w && len(s) > 0 {
		_, size := utf8.DecodeRuneInString(s)
		s = s[size:]
	}
	return s
}

// getLines splits a string into lines and returns the widest width.
func getLines(s string) ([]string, int) {
	lines := strings.Split(s, "\n")
	w := 0
	for _, l := range lines {
		if lw := StringWidth(l); lw > w {
			w = lw
		}
	}
	return lines, w
}

// JoinHorizontal joins blocks horizontally, aligned to top.
func JoinHorizontal(strs ...string) string {
	if len(strs) == 0 {
		return ""
	}
	if len(strs) == 1 {
		return strs[0]
	}
	blocks := make([][]string, len(strs))
	maxWidths := make([]int, len(strs))
	maxHeight := 0
	for i, s := range strs {
		blocks[i], maxWidths[i] = getLines(s)
		if len(blocks[i]) > maxHeight {
			maxHeight = len(blocks[i])
		}
	}
	for i := range blocks {
		for len(blocks[i]) < maxHeight {
			blocks[i] = append(blocks[i], "")
		}
	}
	var b strings.Builder
	for i := 0; i < maxHeight; i++ {
		for j, block := range blocks {
			b.WriteString(block[i])
			pad := maxWidths[j] - StringWidth(block[i])
			if pad > 0 {
				b.WriteString(strings.Repeat(" ", pad))
			}
		}
		if i < maxHeight-1 {
			b.WriteByte('\n')
		}
	}
	return b.String()
}

// JoinVertical joins blocks vertically, aligned left, padding lines.
func JoinVertical(strs ...string) string {
	if len(strs) == 0 {
		return ""
	}
	if len(strs) == 1 {
		return strs[0]
	}
	var blocks [][]string
	maxWidth := 0
	for _, s := range strs {
		lines, w := getLines(s)
		blocks = append(blocks, lines)
		if w > maxWidth {
			maxWidth = w
		}
	}
	var b strings.Builder
	for i, block := range blocks {
		for j, line := range block {
			b.WriteString(line)
			pad := maxWidth - StringWidth(line)
			if pad > 0 {
				b.WriteString(strings.Repeat(" ", pad))
			}
			if !(i == len(blocks)-1 && j == len(block)-1) {
				b.WriteByte('\n')
			}
		}
	}
	return b.String()
}
EOF
echo done"}

