package main

import (
	"fmt"
	"math"
	"os"
	"strconv"
	"strings"

	colorful "github.com/lucasb-eyer/go-colorful"
)

type Profile int

const (
	TrueColor Profile = iota
	ANSI256
	ANSI
	Ascii
)

var colorProfile = Ascii

func detectProfile(isTTY bool) Profile {
	if !isTTY {
		return Ascii
	}
	if os.Getenv("GOOGLE_CLOUD_SHELL") == "true" {
		return TrueColor
	}
	term := os.Getenv("TERM")
	colorTerm := os.Getenv("COLORTERM")
	switch strings.ToLower(colorTerm) {
	case "24bit", "truecolor":
		if strings.HasPrefix(term, "screen") {
			if os.Getenv("TERM_PROGRAM") != "tmux" {
				return ANSI256
			}
		}
		return TrueColor
	case "yes", "true":
		return ANSI256
	}
	switch term {
	case "xterm-kitty", "wezterm":
		return TrueColor
	case "linux":
		return ANSI
	}
	if strings.Contains(term, "256color") {
		return ANSI256
	}
	if strings.Contains(term, "color") {
		return ANSI
	}
	if strings.Contains(term, "ansi") {
		return ANSI
	}
	return Ascii
}

// Color is a terminal color.
type Color interface {
	Sequence(bg bool) string
}

type ANSIColor int
type ANSI256Color int
type RGBColor string

func (c ANSIColor) Sequence(bg bool) string {
	col := int(c)
	bgMod := func(c int) int {
		if bg {
			return c + 10
		}
		return c
	}
	if col < 8 {
		return fmt.Sprintf("%d", bgMod(col)+30)
	}
	return fmt.Sprintf("%d", bgMod(col-8)+90)
}

func (c ANSI256Color) Sequence(bg bool) string {
	prefix := "38"
	if bg {
		prefix = "48"
	}
	return fmt.Sprintf("%s;5;%d", prefix, c)
}

func (c RGBColor) Sequence(bg bool) string {
	f, err := colorful.Hex(string(c))
	if err != nil {
		return ""
	}
	prefix := "38"
	if bg {
		prefix = "48"
	}
	return fmt.Sprintf("%s;2;%d;%d;%d", prefix, uint8(f.R*255), uint8(f.G*255), uint8(f.B*255))
}

