const (
	seqEraseLineRight   = "\x1b[K"
	seqEraseScreenBelow = "\x1b[J"
	seqEraseEntireLine  = "\x1b[2K"
	seqEraseEntireScr   = "\x1b[2J"
	seqHome             = "\x1b[H"
	seqHideCursor       = "\x1b[?25l"
	seqShowCursor       = "\x1b[?25h"
	seqAltScreenOn      = "\x1b[?1049h"
	seqAltScreenOff     = "\x1b[?1049l"
	seqBracketedOn      = "\x1b[?2004h"
	seqBracketedOff     = "\x1b[?2004l"
	seqMouseOff         = "\x1b[?1002l\x1b[?1003l\x1b[?1006l"
)

func cursorUp(n int) string {
	if n <= 1 {
		return "\x1b[A"
	}
	return "\x1b[" + strconv.Itoa(n) + "A"
}

func cursorBackward(n int) string {
	if n <= 1 {
		return "\x1b[D"
	}
	return "\x1b[" + strconv.Itoa(n) + "D"
}

func cursorPosition(col, row int) string {
	if row <= 0 && col <= 0 {
		return seqHome
	}
	var r, c string
	if row > 0 {
		r = strconv.Itoa(row)
	}
	if col > 0 {
		c = strconv.Itoa(col)
	}
	return "\x1b[" + r + ";" + c + "H"
}

type renderer struct {
	mtx               sync.Mutex
	out               io.Writer
	buf               bytes.Buffer
	lastRender        string
	lastRenderedLines []string
	linesRendered     int
	altLinesRendered  int
	width, height     int
	altScreenActive   bool
	cursorHidden      bool
	bpActive          bool
	ticker            *time.Ticker
	done              chan struct{}
	stopped           chan struct{}
	running           bool
}

func newRenderer(out io.Writer) *renderer {
	return &renderer{out: out}
}

func (r *renderer) execute(seq string) {
	_, _ = io.WriteString(r.out, seq)
}

func (r *renderer) start() {
	r.ticker = time.NewTicker(time.Second / 60)
	r.done = make(chan struct{})
	r.stopped = make(chan struct{})
	r.running = true
	go r.listen(r.ticker, r.done, r.stopped)
}

func (r *renderer) listen(t *time.Ticker, done, stopped chan struct{}) {
	defer close(stopped)
	for {
		select {
		case <-done:
			t.Stop()
			return
		case <-t.C:
			r.flush()
		}
	}
}

