	r.mtx.Lock()
	defer r.mtx.Unlock()
	r.cursorHidden = true
	r.execute(seqHideCursor)
}

func (r *renderer) showCursor() {
	r.mtx.Lock()
	defer r.mtx.Unlock()
	r.cursorHidden = false
	r.execute(seqShowCursor)
}

