func fdSet(set *syscall.FdSet, fd int) {
	set.Bits[fd/64] |= 1 << (uint(fd) % 64)
}

func fdIsSet(set *syscall.FdSet, fd int) bool {
	return set.Bits[fd/64]&(1<<(uint(fd)%64)) != 0
}

func (c *cancelReader) Read(b []byte) (int, error) {
	for {
		var rset syscall.FdSet
		fdSet(&rset, c.fd)
		fdSet(&rset, c.pr)
		maxfd := c.fd
		if c.pr > maxfd {
			maxfd = c.pr
		}
		_, err := syscall.Select(maxfd+1, &rset, nil, nil, nil)
		if err != nil {
			if err == syscall.EINTR {
				continue
			}
			return 0, err
		}
		if fdIsSet(&rset, c.pr) {
			return 0, errCanceled
		}
		if fdIsSet(&rset, c.fd) {
			n, err := syscall.Read(c.fd, b)
			if err != nil {
				if err == syscall.EINTR || err == syscall.EAGAIN {
					continue
				}
				return n, err
			}
			if n == 0 {
				return 0, errors.New("EOF")
			}
			return n, nil
		}
	}
}

func (c *cancelReader) Cancel() {
	_, _ = syscall.Write(c.pw, []byte{'c'})
}

func (c *cancelReader) Close() {
	syscall.Close(c.pr)
	syscall.Close(c.pw)
}

// readInputs reads from the reader and sends messages to the channel.
func readInputs(r *cancelReader, send func(interface{})) {
	defer close(r.stopped)
	var buf [256]byte
	var leftOver []byte
	for {
		n, err := r.Read(buf[:])
		if err != nil {
			return
		}
		b := buf[:n]
		if len(leftOver) > 0 {
			b = append(leftOver, b...)
		}
		canHaveMore := n == len(buf)
		leftOver = nil
		for i, w := 0, 0; i < len(b); i += w {
			var msg interface{}
			w, msg = detectOneMsg(b[i:], canHaveMore)
			if w == 0 {
				leftOver = append([]byte{}, b[i:]...)
				break
			}
			if msg != nil {
				send(msg)
			}
		}
	}
}
