package main

import (
	_ "embed"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"unicode"
)

//go:embed etc/icons
var defaultIcons string

type iconMap map[string]string

var icons iconMap

func parseIconFields(line string) []string {
	var fields []string
	var cur strings.Builder
	inField := false
	var quote rune
	for _, r := range line {
		if quote != 0 {
			if r == quote {
				quote = 0
				continue
			}
			cur.WriteRune(r)
			continue
		}
		if r == '\'' || r == '"' {
			quote = r
			inField = true
			continue
		}
		if r == '#' && !inField {
			break
		}
		if unicode.IsSpace(r) {
			if inField {
				fields = append(fields, cur.String())
				cur.Reset()
				inField = false
			}
			continue
		}
		cur.WriteRune(r)
		inField = true
	}
	if inField {
		fields = append(fields, cur.String())
	}
	return fields
}

func parseIcons() iconMap {
	im := iconMap{}
	for _, line := range strings.Split(defaultIcons, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || line[0] == '#' {
			continue
		}
		f := parseIconFields(line)
		if len(f) < 2 {
			continue
		}
		im[f[0]] = f[1]
	}
	return im
}

func (im iconMap) has(k string) bool {
	_, ok := im[k]
	return ok
}

func (im iconMap) get(info fs.FileInfo) string {
	if info == nil {
		return ""
	}
	mode := info.Mode()
	var key string
	switch {
	case info.IsDir() && mode&os.ModeSticky != 0 && mode&0002 != 0 && im.has("tw"):
		key = "tw"
	case info.IsDir() && mode&0002 != 0 && im.has("ow"):
		key = "ow"
	case info.IsDir() && mode&os.ModeSticky != 0 && im.has("st"):
		key = "st"
	case info.IsDir() && im.has("di"):
		key = "di"
	case mode&os.ModeNamedPipe != 0 && im.has("pi"):
		key = "pi"
	case mode&os.ModeSocket != 0 && im.has("so"):
		key = "so"
	case mode&os.ModeDevice != 0 && im.has("bd"):
		key = "bd"
	case mode&os.ModeCharDevice != 0 && im.has("cd"):
		key = "cd"
	case mode&os.ModeSetuid != 0 && im.has("su"):
		key = "su"
	case mode&os.ModeSetgid != 0 && im.has("sg"):
		key = "sg"
	case mode&0111 != 0 && im.has("ex"):
		key = "ex"
	}
	if val, ok := im[key]; ok && key != "" {
		return val
	}
	name := info.Name()
	if val, ok := im["*"+strings.ToLower(name)]; ok {
		return val
	}
	ext := fileExt(info)
	if ext != "" {
		if val, ok := im["*"+strings.ToLower(ext)]; ok {
			return val
		}
	}
	if val, ok := im["fi"]; ok {
		return val
	}
	return " "
}

func fileExt(info fs.FileInfo) string {
	if info.IsDir() {
		return ""
	}
	name := info.Name()
	if strings.Count(name, ".") == 1 && name[0] == '.' {
		return ""
	}
	return filepath.Ext(name)
}
