package main

import (
	"os"
	"os/exec"
	"os/signal"
	"sync"
	"syscall"
	"time"
)

type Msg interface{}

type WindowSizeMsg struct{ Width, Height int }
type quitMsg struct{}
type repaintMsg struct{}

// Cmd is a function run asynchronously producing a message.
type Cmd func() Msg

type execCmd struct {
	cmd *exec.Cmd
	fn  func(error) Msg
}

type Program struct {
	model     *model
	input     *os.File
	output    *os.File
	renderer  *renderer
	msgs      chan Msg
	reader    *cancelReader
	oldState  *syscall.Termios
	outIsTTY  bool
	altScreen bool
	mu        sync.Mutex
	execReq   chan execCmd
}

func (p *Program) Send(m Msg) {
	go func() { p.msgs <- m }()
}

func (p *Program) initTerminal() error {
	st, err := makeRaw(p.input.Fd())
	if err == nil {
		p.oldState = st
	}
	p.renderer.hideCursor()
	return nil
}

func (p *Program) restoreInput() {
	if p.oldState != nil {
		restoreTerm(p.input.Fd(), p.oldState)
	}
}

func (p *Program) startReader() error {
	r, err := newCancelReader(p.input)
	if err != nil {
		return err
	}
	p.reader = r
	go readInputs(r, func(m interface{}) { p.msgs <- m })
	return nil
}

func (p *Program) stopReader() {
	if p.reader != nil {
		p.reader.Cancel()
		select {
		case <-p.reader.stopped:
		case <-time.After(500 * time.Millisecond):
		}
		p.reader.Close()
		p.reader = nil
	}
}

func (p *Program) checkResize() {
	if !p.outIsTTY {
		return
	}
	w, h, err := getSize(p.output.Fd())
	if err != nil {
		return
	}
	p.msgs <- WindowSizeMsg{Width: w, Height: h}
}

func (p *Program) restoreTerminalState() {
	p.renderer.disableBracketedPaste()
	p.renderer.showCursor()
	p.renderer.disableMouse()
	if p.renderer.altScreenActive {
		p.renderer.exitAltScreen()
		time.Sleep(10 * time.Millisecond)
	}
	p.restoreInput()
}

func (p *Program) runCmd(c Cmd) {
	if c == nil {
		return
	}
	go func() {
		if m := c(); m != nil {
			p.msgs <- m
		}
	}()
}

func (p *Program) doExec(e execCmd) {
	// Release terminal.
	p.stopReader()
	p.renderer.stop()
	wasAlt := p.renderer.altScreenActive
	p.restoreTerminalState()

	e.cmd.Stdin = p.input
	e.cmd.Stdout = p.output
	e.cmd.Stderr = os.Stderr
	err := e.cmd.Run()

	// Restore terminal.
	_ = p.initTerminal()
	_ = p.startReader()
	if wasAlt {
		p.renderer.enterAltScreen()
	} else {
		p.Send(repaintMsg{})
	}
	p.renderer.start()
	p.renderer.enableBracketedPaste()
	go p.checkResize()
	if e.fn != nil {
		res := e.fn(err)
		if res != nil {
			p.Send(res)
		}
	}
}

func (p *Program) handleSignals() {
	sig := make(chan os.Signal, 1)
	signal.Notify(sig, syscall.SIGWINCH)
	go func() {
		for range sig {
			p.checkResize()
		}
	}()
	term := make(chan os.Signal, 1)
	signal.Notify(term, syscall.SIGINT, syscall.SIGTERM)
	go func() {
		for range term {
			p.msgs <- KeyMsg{Type: 3}
		}
	}()
}

// Run runs the program. It returns after the model quits.
func (p *Program) Run(startAlt bool) {
	p.msgs = make(chan Msg, 64)
	p.renderer = newRenderer(p.output)
	p.handleSignals()
	_ = p.initTerminal()
	if startAlt {
		p.renderer.enterAltScreen()
	}
	p.renderer.enableBracketedPaste()
	p.renderer.start()

	if p.outIsTTY {
		if w, h, err := getSize(p.output.Fd()); err == nil {
			p.renderer.setSize(w, h)
			p.model.Update(WindowSizeMsg{Width: w, Height: h})
		}
	}
	p.renderer.write(p.model.View())
	_ = p.startReader()

	for msg := range p.msgs {
		switch m := msg.(type) {
		case WindowSizeMsg:
			p.renderer.setSize(m.Width, m.Height)
		case repaintMsg:
			p.renderer.mtx.Lock()
			p.renderer.repaint()
			p.renderer.mtx.Unlock()
		}
		res := p.model.Update(msg)
		if res.quit {
			p.finish(res)
			return
		}
		p.renderer.write(p.model.View())
		if res.altScreen != 0 {
			if res.altScreen > 0 {
				p.renderer.enterAltScreen()
			} else {
				p.renderer.exitAltScreen()
			}
		}
		for _, c := range res.cmds {
			p.runCmd(c)
		}
		if res.exec != nil {
			p.doExec(*res.exec)
		}
	}
}

func (p *Program) finish(res updateResult) {
	if res.beforeFinal != nil {
		res.beforeFinal()
	}
	p.renderer.write(p.model.View() + "\n")
	p.stopReader()
	p.renderer.stop()
	p.restoreTerminalState()
}
EOF
echo ok

