	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

const separator = "    "

var (
	mainColor    = "#825DF2"
	barStyle     = Style{fg: "#FFFFFF", bg: "#5C5C5C"}
	searchStyle  = Style{fg: "#FFFFFF", bg: "#499F1C"}
	cursorStyle  = Style{fg: "#FFFFFF", bg: "#825DF2"}
	dangerStyle  = Style{fg: "#FFFFFF", bg: "#FF0000"}
	previewPlain = Style{}
)

type position struct {
	c, r, offset int
}

type toDelete struct {
	id      int
	path    string
	name    string
	countdown int
}

type deleteTickMsg struct{ id int }
type execDoneMsg struct{}

type updateResult struct {
	quit        bool
	cmds        []Cmd
	exec        *execCmd
	altScreen   int
	beforeFinal func()
}

type model struct {
	path           string
	files          []fs.DirEntry
	c, r           int
	columns, rows  int
	offset         int
	width, height  int
	err            error
	searchMode     bool
	search         string
	fuzzyByDefault bool
	previewMode    bool
	showHelp       bool
	hideHidden     bool
	dirOnly        bool
	withBorder     bool
	showIcons      bool
	positions      map[string]position
	prevName       string
	findPrevName   bool
	toBeDeleted    []toDelete
	deleteID       int
	deleteCurrent  bool
	yankSuccess    bool
	yankPath       string
	exitCode       int
	statusBar      *statusProgram
	statusBarSet   bool
}

func (m *model) listHeight() int {
	h := m.height - 1
	if m.statusBarSet || m.yankSuccess || len(m.toBeDeleted) > 0 {
		h--
	}
	if h < 2 {
		h = 2
	}
	return h
}

func (m *model) displayName(f fs.DirEntry) string {
	name := f.Name()
	if m.showIcons {
		info, err := f.Info()
		if err == nil {
			icon := icons.get(info)
			if icon != "" {
				name = icon + " " + name
			}
		}
	}
	if f.IsDir() {
		name += "/"
	}
	return name
}

func ceilDiv(a, b int) int {
	return int(math.Ceil(float64(a) / float64(b)))
}

// computeGrid computes the number of columns and rows for the given names.
func computeGrid(names []string, width, height int) (int, int) {
	n := len(names)
	if n == 0 {
		return 0, 0
	}
	widths := make([]int, n)
	for i, s := range names {
		widths[i] = StringWidth(s)
	}
	var c0 int
	if n > 100 {
		c0 = 2
	} else {
		R := height / 3
		if R < 1 {
			R = 1
		}
		c0 = n / R
		lo := ceilDiv(n, 10)
		if lo > 4 {
			lo = 4
		}
		if c0 < lo {
			c0 = lo
		}
		if c0 > 15 {
			c0 = 15
		}
	}
	if c0 > n {
		c0 = n
	}
	if c0 < 1 {
		c0 = 1
	}
	for c := c0; c >= 1; c-- {
		r := ceilDiv(n, c)
		cc := ceilDiv(n, r)
		if c == 1 {
			return cc, r
		}
		total := 0
		for i := 0; i < cc; i++ {
			mw := 0
			for j := i * r; j < (i+1)*r && j < n; j++ {
				if widths[j] > mw {
					mw = widths[j]
				}
			}
			total += mw
			if i > 0 {
				total += len(separator)
			}
		}
		if total <= width {
			return cc, r
		}
	}
	return 1, n
}

func (m *model) gridWidth() int {
	w := m.width
	if m.previewMode {
		w = m.width / 2
	}
	return w
}

func (m *model) updateGrid() {
	names := make([]string, len(m.files))
	for i, f := range m.files {
		names[i] = m.displayName(f)
	}
	m.columns, m.rows = computeGrid(names, m.gridWidth(), m.listHeight())
}

func (m *model) index() int {
	return m.c*m.rows + m.r
}

func (m *model) currentFile() (fs.DirEntry, bool) {
	i := m.index()
	if i < 0 || i >= len(m.files) || len(m.files) == 0 {
		return nil, false
	}
	return m.files[i], true
}

func (m *model) fileName() (string, bool) {
	f, ok := m.currentFile()
	if !ok {
		return "", false
	}
	return f.Name(), true
}

func (m *model) filePath() (string, bool) {
	name, ok := m.fileName()
	if !ok {
		return "", false
	}
	return filepath.Join(m.path, name), true
}

func (m *model) isPendingDelete(p string) bool {
	for _, d := range m.toBeDeleted {
		if d.path == p {
			return true
		}
	}
	return false
}

func (m *model) list() {
	m.files = nil
	m.err = nil
	entries, err := os.ReadDir(m.path)
	if err != nil {
		m.err = err
		return
	}
	for _, e := range entries {
		if m.hideHidden && strings.HasPrefix(e.Name(), ".") {
			continue
		}
		if m.dirOnly && !e.IsDir() {
			continue
		}
		if m.isPendingDelete(filepath.Join(m.path, e.Name())) {
			continue
		}
		m.files = append(m.files, e)
	}
	if m.findPrevName {
		m.findPrevName = false
		m.updateGrid()
		for i, f := range m.files {
			if f.Name() == m.prevName {
				m.selectIndex(i)
				break
			}
		}
	}
}

func (m *model) selectIndex(i int) {
	if m.rows <= 0 {
		return
	}
	m.c = i / m.rows
	m.r = i % m.rows
}

func (m *model) keepCursorByName(fn func()) {
	name, ok := m.fileName()
	fn()
	m.updateGrid()
	if ok {
		for i, f := range m.files {
			if f.Name() == name {
				m.selectIndex(i)
				break
			}
		}
	}
}

func (m *model) moveUp() {
	m.r--
	if m.r < 0 {
		m.r = m.rows - 1
		m.c--
	}
	if m.c < 0 {
		m.r = m.rows - 1 - (m.columns*m.rows - len(m.files))
		m.c = m.columns - 1
	}
}

func (m *model) moveDown() {
	m.r++
	if m.r >= m.rows {
		m.r = 0
		m.c++
	}
	if m.c >= m.columns {
		m.c = 0
	}
	if m.c == m.columns-1 && (m.columns-1)*m.rows+m.r >= len(m.files) {
		m.r = 0
		m.c = 0
	}
}

func (m *model) moveLeft() {
	m.c--
	if m.c < 0 {
		m.c = m.columns - 1
	}
	if m.c == m.columns-1 && (m.columns-1)*m.rows+m.r >= len(m.files) {
		m.r = m.rows - 1 - (m.columns*m.rows - len(m.files))
		m.c = m.columns - 1
	}
}

func (m *model) moveRight() {
	m.c++
	if m.c >= m.columns {
		m.c = 0
	}
	if m.c == m.columns-1 && (m.columns-1)*m.rows+m.r >= len(m.files) {
		m.r = m.rows - 1 - (m.columns*m.rows - len(m.files))
		m.c = m.columns - 1
	}
}

func (m *model) updateOffset() {
	height := m.listHeight()
	if m.r >= m.offset+height {
		m.offset = m.r - height + 1
	} else if m.r < m.offset {
		m.offset = m.r
	}
}

func (m *model) saveCursorPosition() {
	m.positions[m.path] = position{c: m.c, r: m.r, offset: m.offset}
}

func (m *model) restorePosition() bool {
	if p, ok := m.positions[m.path]; ok {
		m.c = p.c
		m.r = p.r
		m.offset = p.offset
		return true
	}
	return false
}

func lookupEnv(names []string, def string) string {
	for _, n := range names {
		if v, ok := os.LookupEnv(n); ok && v != "" {
			return v
		}
	}
	return def
}

var openWith = map[string]string{}

func parseOpenWith() {
	v := os.Getenv("WALK_OPEN_WITH")
	if v == "" {
		return
	}
	for _, pair := range strings.Split(v, ";") {
		pair = strings.TrimSpace(pair)
		parts := strings.Split(pair, ":")
		if len(parts) != 2 {
			continue
		}
		openWith[parts[0]] = parts[1]
	}
}

func (m *model) openEditor() *execCmd {
	filePath, ok := m.filePath()
	if !ok {
		return nil
	}
	ext := strings.ToLower(strings.TrimPrefix(filepath.Ext(filePath), "."))
	cmdline, ok := openWith[ext]
	if !ok {
		cmdline = lookupEnv([]string{"WALK_EDITOR", "EDITOR"}, "less")
	}
	parts := strings.Split(cmdline, " ")
	args := append(parts[1:], filePath)
	cmd := exec.Command(parts[0], args...)
	return &execCmd{cmd: cmd, fn: func(err error) Msg { return execDoneMsg{} }}
}

func deleteTick(id int) Cmd {
	return func() Msg {
		time.Sleep(time.Second)
		return deleteTickMsg{id: id}
	}
}

func removeFile(path string) {
	if cmd := os.Getenv("WALK_REMOVE_CMD"); cmd != "" {
		c := exec.Command(cmd, path)
		_ = c.Run()
		return
	}
	_ = os.RemoveAll(path)
}

func (m *model) performPendingDeletes() {
	for _, d := range m.toBeDeleted {
		removeFile(d.path)
	}
	m.toBeDeleted = nil
}

func (m *model) Update(msg Msg) updateResult {
	var res updateResult
	switch msg := msg.(type) {
	case WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.positions = map[string]position{}
		m.keepCursorByName(func() {})
		m.updateOffset()
		return res
	case deleteTickMsg:
		for i := range m.toBeDeleted {
			d := &m.toBeDeleted[i]
			if d.id != msg.id {
				continue
			}
			if d.countdown > 0 {
				d.countdown--
				res.cmds = append(res.cmds, deleteTick(d.id))
			} else {
				removeFile(d.path)
				m.toBeDeleted = append(m.toBeDeleted[:i], m.toBeDeleted[i+1:]...)
			}
			break
		}
		return res
	case KeyMsg:
		return m.handleKey(msg)
	}
	return res
}

func (m *model) applyFuzzy() {
	names := make([]string, len(m.files))
	for i, f := range m.files {
		names[i] = f.Name()
	}
	matches := fuzzyFind(m.search, names)
	if len(matches) > 0 {
		m.selectIndex(matches[0].Index)
	}
}

func (m *model) handleKey(msg KeyMsg) updateResult {
	var res updateResult
	k := msg.String()

	if m.searchMode {
		if k == "/" && !m.fuzzyByDefault {
			m.searchMode = false
			m.search = ""
			goto after
		} else if k == "backspace" {
			if len(m.search) > 0 {
				r := []rune(m.search)
				m.search = string(r[:len(r)-1])
				return res
			} else if !m.fuzzyByDefault {
				m.searchMode = false
				return res
			}
		} else if msg.Type == KeyRunes {
			m.search += string(msg.Runes)
			m.applyFuzzy()
			m.updateOffset()
			return res
		}
	}

	switch k {
	case "ctrl+c":
		m.exitCode = 2
		pend := m.toBeDeleted
		res.quit = true
		res.beforeFinal = func() {
			for _, d := range pend {
				fmt.Fprintf(os.Stderr, "Was not deleted: %v\n", d.path)
			}
		}
		return res
	case "esc", "q":
		m.performPendingDeletes()
		m.exitCode = 0
		res.quit = true
		path := m.path
		res.beforeFinal = func() {}
		quitPath = path
		return res
	case "enter":
		if !m.fuzzyByDefault {
			m.searchMode = false
		}
		m.search = ""
		filePath, ok := m.filePath()
		if !ok {
			return res
		}
		fi, err := os.Stat(filePath)
		if err != nil {
			panicCaught(err)
		}
		if fi.IsDir() {
			m.path = filePath
			if !m.restorePosition() {
				m.c, m.r, m.offset = 0, 0, 0
			}
			m.list()
		} else {
			res.exec = m.openEditor()
			return res
		}
	case "backspace":
		if m.fuzzyByDefault {
			m.search = ""
		} else {
			m.searchMode = false
		}
		m.prevName = filepath.Base(m.path)
		m.path = filepath.Join(m.path, "..")
		if !m.restorePosition() {
			m.findPrevName = true
		}
		m.list()
	case "up", "k":
		m.moveUp()
	case "shift+up", "pgup", "g":
		m.r = 0
	case "down", "j":
		m.moveDown()
	case "shift+down", "pgdown", "G":
		m.r = m.rows - 1
		if m.c == m.columns-1 && (m.columns-1)*m.rows+m.r >= len(m.files) {
			m.r = m.rows - 1 - (m.columns*m.rows - len(m.files))
		}
	case "left", "h":
		m.moveLeft()
	case "shift+left":
		m.c = 0
	case "right", "l":
		m.moveRight()
	case "shift+right":
		m.c = m.columns - 1
		if (m.columns-1)*m.rows+m.r >= len(m.files) {
			m.r = m.rows - 1 - (m.columns*m.rows - len(m.files))
		}
	case "home":
		m.c, m.r = 0, 0
	case "end":
		m.c = m.columns - 1
		m.r = m.rows - 1 - (m.columns*m.rows - len(m.files))
	case "/":
		m.searchMode = true
		m.search = ""
	case " ":
		m.keepCursorByName(func() { m.previewMode = !m.previewMode })
		m.positions = map[string]position{}
		m.updateOffset()
		if m.previewMode {
			res.altScreen = 1
		} else {
			res.altScreen = -1
		}
		return res
	case "d", "delete":
		filePath, ok := m.filePath()
		if !ok {
			return res
		}
		if m.deleteCurrent {
			m.deleteCurrent = false
			m.deleteID++
			name, _ := m.fileName()
			m.toBeDeleted = append(m.toBeDeleted, toDelete{id: m.deleteID, path: filePath, name: name, countdown: 5})
			m.list()
			res.cmds = append(res.cmds, deleteTick(m.deleteID))
			return res
		}
		m.deleteCurrent = true
		return res
	case "u":
		if len(m.toBeDeleted) > 0 {
			m.toBeDeleted = m.toBeDeleted[:len(m.toBeDeleted)-1]
			m.list()
		}
	case "y":
		filePath, ok := m.filePath()
		if !ok {
			return res
		}
		copyToClipboard(filePath)
		m.yankSuccess = true
		m.yankPath = filePath
		return res
	case ".":
		m.hideHidden = !m.hideHidden
		m.list()
	case "?":
		m.showHelp = !m.showHelp
		return res
	}
after:
	m.deleteCurrent = false
	m.yankSuccess = false
	m.showHelp = false
	m.updateGrid()
	m.updateOffset()
	m.saveCursorPosition()
	return res
}

var quitPath string

func panicCaught(err error) {
	panic(caughtPanic{err})
}

type caughtPanic struct{ err error }
EOF
echo ok

output.arguments:
{"command":"cd /workspace && cat > view.go <<'EOF'
package main

import (
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"unicode/utf8"
)

const helpKeys = `    arrows, hjkl  Move cursor
    enter         Enter directory
    backspace     Exit directory
    space         Toggle preview
    esc, q        Exit with cd
    ctrl+c        Exit without cd
    /             Fuzzy search
    d, delete     Delete file or dir
    y             Copy to clipboard
    .             Hide hidden files
    ?             Show help`

func usage() string {
	return "\n  walk " + version + "\n\n  Usage: walk [path]\n\n" + helpKeys + `

  Flags:

    --icons        display icons
    --dir-only     show dirs only
    --hide-hidden  hide hidden files
    --preview      display preview
    --with-border  preview with border
    --fuzzy        fuzzy mode

`
}

func padRight(s string, w int) string {
	sw := StringWidth(s)
	if sw < w {
		return s + strings.Repeat(" ", w-sw)
	}
	return s
}

// renderGrid renders the names in a grid. cursor is the index to highlight (or -1).
func renderGrid(names []string, columns, rows int, cursor int, cursorSt Style) []string {
	if columns == 0 || rows == 0 {
		return nil
	}
	cells := make([][]string, columns)
	n := 0
	for i := 0; i < columns; i++ {
		cells[i] = make([]string, rows)
		maxW := 0
		start := n
		for j := 0; j < rows; j++ {
			name := ""
			if n < len(names) {
				name = names[n]
			}
			if w := StringWidth(name); w > maxW {
				maxW = w
			}
			cells[i][j] = name
			n++
		}
		for j := 0; j < rows; j++ {
			cells[i][j] = padRight(cells[i][j], maxW)
			if start+j == cursor && cursor < len(names) {
				cells[i][j] = cursorSt.Render(cells[i][j])
			}
		}
	}
	out := make([]string, rows)
	for j := 0; j < rows; j++ {
		row := make([]string, columns)
		for i := 0; i < columns; i++ {
			row[i] = cells[i][j]
		}
		out[j] = strings.Join(row, separator)
	}
	return out
}

func (m *model) location() string {
	location := m.path
	if home, err := os.UserHomeDir(); err == nil {
		location = strings.Replace(location, home, "~", 1)
	}
	return location
}

func (m *model) statusLine() (string, bool) {
	if len(m.toBeDeleted) > 0 {
		d := m.toBeDeleted[len(m.toBeDeleted)-1]
		return dangerStyle.Render(fmt.Sprintf("%v deleted. (u)ndo %v", d.name, d.countdown)), true
	}
	if m.yankSuccess {
		return barStyle.Render("copied: " + m.yankPath), true
	}
	if m.statusBar != nil {
		f, ok := m.currentFile()
		if !ok {
			return "", false
		}
		s := m.statusBar.Run(f, m.files, m.path)
		return barStyle.Render(s), true
	}
	return "", false
}

func (m *model) View() string {
	if m.showHelp {
		return barStyle.Render("help") + "\n\n" + helpKeys + "\n\n"
	}
	m.updateGrid()

	var output []string
	listWidth := 0
	if m.err != nil {
		output = strings.Split(renderBox(m.err.Error()), "\n")
	} else if len(m.files) == 0 {
		output = strings.Split(renderBox("No files"), "\n")
	} else {
		names := make([]string, len(m.files))
		for i, f := range m.files {
			names[i] = m.displayName(f)
		}
		st := cursorStyle
		if m.deleteCurrent {
			st = dangerStyle
		}
		cur := -1
		if m.r < m.rows && m.c < m.columns && m.r >= 0 && m.c >= 0 {
			cur = m.index()
		}
		output = renderGrid(names, m.columns, m.rows, cur, st)
		for _, l := range output {
			if w := StringWidth(l); w > listWidth {
				listWidth = w
			}
		}
		height := m.listHeight()
		if m.height > 0 {
			end := m.offset + height
			if end > len(output) {
				end = len(output)
			}
			start := m.offset
			if start > end {
				start = end
			}
			if start < 0 {
				start = 0
			}
			output = output[start:end]
		}
	}

	location := m.location()
	filter := ""
	if m.searchMode && (!m.fuzzyByDefault || m.search != "") {
		filter = "/" + m.search
	}
	budget := m.width
	if m.previewMode {
		budget = listWidth
		if bw := StringWidth(filepath.Base(location)); bw > budget {
			budget = bw
		}
	}
	fw := StringWidth(filter)
	if StringWidth(location)+fw > budget {
		if fw > budget {
			location = ""
		} else {
			location = truncateLeftRunes(location, budget-fw)
		}
	}
	title := barStyle.Render(location) + searchStyle.Render(filter)

	main := title + "\n" + strings.Join(output, "\n")
	if s, ok := m.statusLine(); ok {
		main += "\n" + s
	}

	if m.previewMode {
		leftWidth := 0
		for _, l := range strings.Split(main, "\n") {
			if w := StringWidth(l); w > leftWidth {
				leftWidth = w
			}
		}
		gap := 2
		if m.withBorder {
			gap = 3
		}
		pw := m.width - leftWidth - gap
		preview := m.renderPreview(pw)
		if m.withBorder {
			preview = applyLeftBorder(preview)
			return JoinHorizontal(main, " ", preview)
		}
		return JoinHorizontal(main, "  ", preview)
	}
	return main
}

func applyLeftBorder(s string) string {
	lines, w := getLines(s)
	border := styled(borderSeq(), "│")
	for i, l := range lines {
		lines[i] = border + " " + padRight(l, w)
	}
	return strings.Join(lines, "\n")
}

func borderSeq() []string {
	if colorProfile == Ascii {
		return nil
	}
	if c := colorProfile.Color(mainColor); c != nil {
		if sq := c.Sequence(false); sq != "" {
			return []string{sq}
		}
	}
	return nil
}

func (m *model) renderPreview(width int) string {
	f, ok := m.currentFile()
	if !ok {
		return renderBox("Invalid file to preview")
	}
	filePath := filepath.Join(m.path, f.Name())
	title := barStyle.Render(f.Name())
	fi, err := os.Stat(filePath)
	if err != nil {
		return title + "\n" + renderBox(err.Error())
	}
	maxLines := m.height - 1
	if fi.IsDir() {
		entries, err := os.ReadDir(filePath)
		if err != nil {
			return title + "\n" + renderBox(err.Error())
		}
		if len(entries) == 0 {
			return title + "\n" + renderBox("No files")
		}
		names := make([]string, len(entries))
		for i, e := range entries {
			names[i] = m.displayName(e)
		}
