package main

import (
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"unicode/utf8"
)

const helpKeys = `    arrows, hjkl  Move cursor
    enter         Enter directory
    backspace     Exit directory
    space         Toggle preview
    esc, q        Exit with cd
    ctrl+c        Exit without cd
    /             Fuzzy search
    d, delete     Delete file or dir
    y             Copy to clipboard
    .             Hide hidden files
    ?             Show help`

func usage() string {
	return "\n  walk " + version + "\n\n  Usage: walk [path]\n\n" + helpKeys + `

  Flags:

    --icons        display icons
    --dir-only     show dirs only
    --hide-hidden  hide hidden files
    --preview      display preview
    --with-border  preview with border
    --fuzzy        fuzzy mode

`
}

func padRight(s string, w int) string {
	sw := StringWidth(s)
	if sw < w {
		return s + strings.Repeat(" ", w-sw)
	}
	return s
}

// renderGrid renders the names in a grid. cursor is the index to highlight (or -1).
func renderGrid(names []string, columns, rows int, cursor int, cursorSt Style) []string {
	if columns == 0 || rows == 0 {
		return nil
	}
	cells := make([][]string, columns)
	n := 0
	for i := 0; i < columns; i++ {
		cells[i] = make([]string, rows)
		maxW := 0
		start := n
		for j := 0; j < rows; j++ {
			name := ""
			if n < len(names) {
				name = names[n]
			}
			if w := StringWidth(name); w > maxW {
				maxW = w
			}
			cells[i][j] = name
			n++
		}
		for j := 0; j < rows; j++ {
			cells[i][j] = padRight(cells[i][j], maxW)
			if start+j == cursor && cursor < len(names) {
				cells[i][j] = cursorSt.Render(cells[i][j])
			}
		}
	}
	out := make([]string, rows)
	for j := 0; j < rows; j++ {
		row := make([]string, columns)
		for i := 0; i < columns; i++ {
			row[i] = cells[i][j]
		}
		out[j] = strings.Join(row, separator)
	}
	return out
}

func (m *model) location() string {
	location := m.path
	if home, err := os.UserHomeDir(); err == nil {
		location = strings.Replace(location, home, "~", 1)
	}
	return location
}

func (m *model) statusLine() (string, bool) {
	if len(m.toBeDeleted) > 0 {
		d := m.toBeDeleted[len(m.toBeDeleted)-1]
		return dangerStyle.Render(fmt.Sprintf("%v deleted. (u)ndo %v", d.name, d.countdown)), true
	}
	if m.yankSuccess {
		return barStyle.Render("copied: " + m.yankPath), true
	}
	if m.statusBar != nil {
		f, ok := m.currentFile()
		if !ok {
			return "", false
		}
		s := m.statusBar.Run(f, m.files, m.path)
		return barStyle.Render(s), true
	}
	return "", false
}

func (m *model) View() string {
	if m.showHelp {
		return barStyle.Render("help") + "\n\n" + helpKeys + "\n\n"
	}
	m.updateGrid()

	var output []string
	listWidth := 0
	if m.err != nil {
		output = strings.Split(renderBox(m.err.Error()), "\n")
	} else if len(m.files) == 0 {
		output = strings.Split(renderBox("No files"), "\n")
	} else {
		names := make([]string, len(m.files))
		for i, f := range m.files {
			names[i] = m.displayName(f)
		}
		st := cursorStyle
		if m.deleteCurrent {
			st = dangerStyle
		}
		cur := -1
		if m.r < m.rows && m.c < m.columns && m.r >= 0 && m.c >= 0 {
			cur = m.index()
		}
		output = renderGrid(names, m.columns, m.rows, cur, st)
		for _, l := range output {
			if w := StringWidth(l); w > listWidth {
				listWidth = w
			}
		}
		height := m.listHeight()
		if m.height > 0 {
			end := m.offset + height
			if end > len(output) {
				end = len(output)
			}
			start := m.offset
			if start > end {
				start = end
			}
			if start < 0 {
				start = 0
			}
			output = output[start:end]
		}
	}

	location := m.location()
	filter := ""
	if m.searchMode && (!m.fuzzyByDefault || m.search != "") {
		filter = "/" + m.search
	}
	budget := m.width
	if m.previewMode {
		budget = listWidth
		if bw := StringWidth(filepath.Base(location)); bw > budget {
			budget = bw
		}
	}
	fw := StringWidth(filter)
	if StringWidth(location)+fw > budget {
		if fw > budget {
			location = ""
		} else {
			location = truncateLeftRunes(location, budget-fw)
		}
	}
	title := barStyle.Render(location) + searchStyle.Render(filter)

	main := title + "\n" + strings.Join(output, "\n")
	if s, ok := m.statusLine(); ok {
		main += "\n" + s
	}

	if m.previewMode {
		leftWidth := 0
		for _, l := range strings.Split(main, "\n") {
			if w := StringWidth(l); w > leftWidth {
				leftWidth = w
			}
		}
		gap := 2
		if m.withBorder {
			gap = 3
		}
		pw := m.width - leftWidth - gap
		preview := m.renderPreview(pw)
		if m.withBorder {
			preview = applyLeftBorder(preview)
			return JoinHorizontal(main, " ", preview)
		}
		return JoinHorizontal(main, "  ", preview)
	}
	return main
}

func applyLeftBorder(s string) string {
	lines, w := getLines(s)
	border := styled(borderSeq(), "│")
	for i, l := range lines {
		lines[i] = border + " " + padRight(l, w)
	}
	return strings.Join(lines, "\n")
}

func borderSeq() []string {
	if colorProfile == Ascii {
		return nil
	}
	if c := colorProfile.Color(mainColor); c != nil {
		if sq := c.Sequence(false); sq != "" {
			return []string{sq}
		}
	}
	return nil
}

func (m *model) renderPreview(width int) string {
	f, ok := m.currentFile()
	if !ok {
		return renderBox("Invalid file to preview")
	}
	filePath := filepath.Join(m.path, f.Name())
	title := barStyle.Render(f.Name())
	fi, err := os.Stat(filePath)
	if err != nil {
		return title + "\n" + renderBox(err.Error())
	}
	maxLines := m.height - 1
	if fi.IsDir() {
		entries, err := os.ReadDir(filePath)
		if err != nil {
			return title + "\n" + renderBox(err.Error())
		}
		if len(entries) == 0 {
			return title + "\n" + renderBox("No files")
		}
		names := make([]string, len(entries))
		for i, e := range entries {
			names[i] = m.displayName(e)
		}
		cols, rows := computeGrid(names, m.width/2, m.listHeight())
		out := renderGrid(names, cols, rows, -1, cursorStyle)
		if m.height > 0 && len(out) > maxLines {
			out = out[:max(maxLines, 0)]
		}
		return title + "\n" + strings.Join(out, "\n")
	}
	file, err := os.Open(filePath)
	if err != nil {
		return title + "\n" + err.Error()
	}
	defer file.Close()
	buf := make([]byte, 100*1024)
	n, _ := io.ReadFull(file, buf)
	buf = buf[:n]
	if !utf8.Valid(buf) {
		return title + "\n" + renderBox("No preview available")
	}
	var sb strings.Builder
	for _, c := range buf {
		switch {
		case c == '\n':
			sb.WriteByte(c)
		case c == '\t':
			sb.WriteString("    ")
		case c < 0x20:
		case c >= 0x80:
		default:
			sb.WriteByte(c)
		}
	}
	lines := strings.Split(sb.String(), "\n")
	if m.height > 0 && len(lines) > maxLines {
		lines = lines[:max(maxLines, 0)]
	}
	for i, l := range lines {
		if width >= 0 {
			lines[i] = Truncate(l, width)
		}
	}
	return title + "\n" + strings.Join(lines, "\n")
}
