	"<=": {20, false}, "in": {20, false}, "matches": {20, false}, "contains": {20, false},
	"startsWith": {20, false}, "endsWith": {20, false}, "..": {25, false}, "+": {30, false},
	"-": {30, false}, "*": {60, false}, "/": {60, false}, "%": {60, false}, "**": {100, true},
	"^": {100, true}, "??": {500, false},
	"not in": {20, false}, "not matches": {20, false}, "not contains": {20, false},
	"not startsWith": {20, false}, "not endsWith": {20, false},
}

var predicateBuiltins = map[string]int{
	"all": 2, "none": 2, "any": 2, "one": 2, "filter": 2, "map": 2, "count": 2, "sum": 2,
	"find": 2, "findIndex": 2, "findLast": 2, "findLastIndex": 2, "groupBy": 2, "sortBy": 2, "reduce": 2,
}

type parser struct {
	toks  []token
	i     int
	cur   token
	err   error
	src   string
	depth int
}

func (p *parser) next() {
	if p.i < len(p.toks)-1 {
		p.i++
	}
	p.cur = p.toks[p.i]
}

func (p *parser) errorAt(t token, format string, a ...interface{}) {
	if p.err == nil {
		p.err = &exprError{msg: fmt.Sprintf(format, a...), pos: t.pos, source: p.src}
	}
}

func (p *parser) error(format string, a ...interface{}) {
	p.errorAt(p.cur, format, a...)
}

func (p *parser) is(kind tokKind, vals ...string) bool {
	if p.cur.kind != kind {
		return false
	}
	if len(vals) == 0 {
		return true
	}
	for _, v := range vals {
		if p.cur.value == v {
			return true
		}
	}
	return false
}

func (p *parser) expect(kind tokKind, vals ...string) {
	if p.is(kind, vals...) {
		p.next()
		return
	}
	p.error("unexpected token %v", p.cur)
}

func parseExpr(src string) (node, error) {
	toks, err := lexExpr(src)
	if err != nil {
		return nil, err
	}
	p := &parser{toks: toks, src: src}
	p.cur = toks[0]
	n := p.parseSequence()
	if p.err == nil && p.cur.kind != tEOF {
		p.error("unexpected token %v", p.cur)
	}
	if p.err != nil {
		return nil, p.err
	}
	return n, nil
}

func (p *parser) parseSequence() node {
	start := p.cur
	var nodes []node
	nodes = append(nodes, p.parseExpression(0))
	for p.is(tOperator, ";") && p.err == nil {
		p.next()
		if p.cur.kind == tEOF {
			break
		}
		nodes = append(nodes, p.parseExpression(0))
	}
	if len(nodes) == 1 {
		return nodes[0]
	}
	return &seqNode{base{start.pos}, nodes}
}

func (p *parser) parseExpression(prec int) node {
	if p.err != nil {
		return &nilNode{}
	}
	if prec == 0 && p.is(tOperator, "let") {
		return p.parseLet()
	}
	left := p.parsePrimary()
	prevOp := ""
	opTok := p.cur
	for opTok.kind == tOperator && p.err == nil {
		info, ok := binaryOps[opTok.value]
		if !ok || info.prec < prec {
			break
		}
		p.next()
		if opTok.value == "|" {
			ident := p.cur
			p.expect(tIdent)
			if p.err != nil {
				break
			}
			left = p.parseCall(ident, []node{left})
			goto next
		}
		if prevOp == "??" && opTok.value != "??" {
			p.errorAt(opTok, "Operator (%v) and coalesce expressions (??) cannot be mixed. Wrap either by parentheses.", opTok.value)
			break
		}
		{
			var right node
			if info.right {
				right = p.parseExpression(info.prec)
			} else {
				right = p.parseExpression(info.prec + 1)
			}
			op := opTok.value
			if strings.HasPrefix(op, "not ") {
				left = &unaryNode{base{opTok.pos}, "not", &binaryNode{base{opTok.pos}, op[4:], left, right}}
			} else {
				left = &binaryNode{base{opTok.pos}, op, left, right}
			}
		}
	next:
		prevOp = opTok.value
		opTok = p.cur
	}
	if prec == 0 {
		left = p.parseConditional(left)
	}
	return left
}

func (p *parser) parseLet() node {
	start := p.cur
	p.expect(tOperator, "let")
	name := p.cur
	p.expect(tIdent)
	p.expect(tOperator, "=")
	value := p.parseExpression(0)
	p.expect(tOperator, ";")
	body := p.parseSequence()
	return &letNode{base{start.pos}, name.value, value, body}
}

func (p *parser) parseConditional(n node) node {
	for p.is(tOperator, "?") && p.err == nil {
		qt := p.cur
		p.next()
		var a, b node
		if !p.is(tOperator, ":") {
			a = p.parseExpression(0)
			p.expect(tOperator, ":")
			b = p.parseExpression(0)
		} else {
			p.next()
			a = n
			b = p.parseExpression(0)
		}
		n = &condNode{base{qt.pos}, n, a, b}
	}
	return n
}

func (p *parser) parsePrimary() node {
	t := p.cur
	if t.kind == tOperator {
		if prec, ok := unaryOps[t.value]; ok {
			p.next()
			x := p.parseExpression(prec)
			return p.parsePostfix(&unaryNode{base{t.pos}, t.value, x})
		}
	}
	if p.is(tBracket, "(") {
		p.next()
		e := p.parseSequence()
		p.expect(tBracket, ")")
		return p.parsePostfix(e)
	}
	if p.depth > 0 {
		if p.is(tOperator, "#") || p.is(tOperator, ".") {
			name := ""
			if p.is(tOperator, "#") {
				p.next()
				if p.cur.kind == tIdent {
					name = p.cur.value
					p.next()
				}
			}
			var n node = &pointerNode{base{t.pos}, name}
			if t.value == "." {
				// .name is member of pointer
				return p.parsePostfixFrom(n, t)
			}
			return p.parsePostfix(n)
		}
	} else if p.is(tOperator, "#") || p.is(tOperator, ".") {
		p.error("cannot use pointer accessor outside predicate")
		return &nilNode{}
	}
	return p.parseSecondary()
}

func (p *parser) parseSecondary() node {
	t := p.cur
	var n node
	switch t.kind {
	case tIdent:
		p.next()
		switch t.value {
		case "true":
			n = &boolNode{base{t.pos}, true}
		case "false":
			n = &boolNode{base{t.pos}, false}
		case "nil":
			n = &nilNode{base{t.pos}}
		default:
			if p.is(tBracket, "(") {
				n = p.parseCall(t, nil)
			} else {
				n = &identNode{base{t.pos}, t.value}
			}
		}
	case tNumber:
		p.next()
		v := strings.ReplaceAll(t.value, "_", "")
		lv := strings.ToLower(v)
		switch {
		case strings.HasPrefix(lv, "0x"):
			num, err := strconv.ParseInt(v, 0, 64)
			if err != nil {
				p.error("invalid hex literal: %v", err)
			}
			n = &intNode{base{t.pos}, int(num)}
		case strings.HasPrefix(lv, "0b"):
			num, err := strconv.ParseInt(v, 0, 64)
			if err != nil {
				p.error("invalid binary literal: %v", err)
			}
			n = &intNode{base{t.pos}, int(num)}
		case strings.HasPrefix(lv, "0o"):
			num, err := strconv.ParseInt(v, 0, 64)
			if err != nil {
				p.error("invalid octal literal: %v", err)
			}
			n = &intNode{base{t.pos}, int(num)}
		case strings.ContainsAny(lv, ".e"):
			num, err := strconv.ParseFloat(v, 64)
			if err != nil {
				p.error("invalid float literal: %v", err)
			}
			n = &floatNode{base{t.pos}, num}
		default:
			num, err := strconv.ParseInt(v, 10, 64)
			if err != nil {
				p.error("invalid integer literal: %v", err)
			}
			n = &intNode{base{t.pos}, int(num)}
		}
	case tString:
		p.next()
		n = &stringNode{base{t.pos}, t.value}
	default:
		if p.is(tBracket, "[") {
			n = p.parseArray()
		} else if p.is(tBracket, "{") {
			n = p.parseMap()
		} else {
			p.error("unexpected token %v", t)
			return &nilNode{}
		}
	}
	return p.parsePostfix(n)
}

func (p *parser) parseCall(t token, prefix []node) node {
	if _, ok := predicateBuiltins[t.value]; ok {
		p.expect(tBracket, "(")
		args := append([]node{}, prefix...)
		if len(prefix) == 0 {
			args = append(args, p.parseExpression(0))
			if p.is(tOperator, ",") {
				p.next()
			} else {
				p.error("unexpected token %v", p.cur)
			}
		}
		p.depth++
		start := p.cur
		body := p.parseExpression(0)
		p.depth--
		args = append(args, &closureNode{base{start.pos}, body})
		for p.is(tOperator, ",") && p.err == nil {
			p.next()
			args = append(args, p.parseExpression(0))
		}
		p.expect(tBracket, ")")
		return p.parsePostfix(&callNode{base{t.pos}, &identNode{base{t.pos}, t.value}, args})
	}
	args := p.parseArguments(prefix)
	return &callNode{base{t.pos}, &identNode{base{t.pos}, t.value}, args}
}

func (p *parser) parseArguments(args []node) []node {
	p.expect(tBracket, "(")
	for !p.is(tBracket, ")") && p.err == nil {
		if len(args) > 0 && (len(args) > 0 && p.i > 0 && !(p.toks[p.i-1].kind == tBracket && p.toks[p.i-1].value == "(")) {
			p.expect(tOperator, ",")
		}
		if p.is(tBracket, ")") {
			break
		}
		args = append(args, p.parseExpression(0))
	}
	p.expect(tBracket, ")")
	return args
}

func (p *parser) parseArray() node {
	t := p.cur
	p.expect(tBracket, "[")
	var items []node
	for !p.is(tBracket, "]") && p.err == nil {
		if len(items) > 0 {
			p.expect(tOperator, ",")
			if p.is(tBracket, "]") {
				break
			}
		}
		items = append(items, p.parseExpression(0))
	}
	p.expect(tBracket, "]")
	return &arrayNode{base{t.pos}, items}
}

func (p *parser) parseMap() node {
	t := p.cur
	p.expect(tBracket, "{")
	var keys, values []node
	for !p.is(tBracket, "}") && p.err == nil {
		if len(keys) > 0 {
			p.expect(tOperator, ",")
			if p.is(tBracket, "}") {
				break
			}
		}
		var key node
		switch {
		case p.cur.kind == tNumber || p.cur.kind == tString || p.cur.kind == tIdent:
			key = &stringNode{base{p.cur.pos}, p.cur.value}
			p.next()
		case p.is(tBracket, "("):
			key = p.parseExpression(0)
		default:
			p.error("a map key must be a quoted string, a number, a identifier, or an expression enclosed in parentheses (unexpected token %v)", p.cur)
		}
		p.expect(tOperator, ":")
		keys = append(keys, key)
		values = append(values, p.parseExpression(0))
	}
	p.expect(tBracket, "}")
	return &mapNode{base{t.pos}, keys, values}
}

func (p *parser) parsePostfixFrom(n node, dot token) node {
	// n is pointer, dot is "." token already current
	return p.parsePostfix(n)
}

func (p *parser) parsePostfix(n node) node {
	pt := p.cur
	for (pt.kind == tOperator || pt.kind == tBracket) && p.err == nil {
		optional := pt.value == "?."
		if pt.value == "." || pt.value == "?." {
			p.next()
			prop := p.cur
			if optional && prop.kind == tBracket && prop.value == "[" {
				pt = prop
				continue
			}
			p.next()
			if prop.kind != tIdent && !(prop.kind == tOperator && isIdentWord(prop.value)) {
				p.errorAt(prop, "expected name")
				break
			}
			mn := &memberNode{base{prop.pos}, n, &stringNode{base{prop.pos}, prop.value}, optional, false}
			if p.is(tBracket, "(") {
				mn.method = true
				args := p.parseArguments(nil)
				n = &callNode{base{prop.pos}, mn, args}
			} else {
				n = mn
			}
		} else if pt.value == "[" {
			p.next()
			if p.is(tOperator, ":") {
				p.next()
				var to node
				if !p.is(tBracket, "]") {
					to = p.parseExpression(0)
				}
				n = &sliceNode{base{pt.pos}, n, nil, to}
				p.expect(tBracket, "]")
			} else {
				from := p.parseExpression(0)
				if p.is(tOperator, ":") {
					p.next()
					var to node
					if !p.is(tBracket, "]") {
						to = p.parseExpression(0)
					}
					n = &sliceNode{base{pt.pos}, n, from, to}
					p.expect(tBracket, "]")
				} else {
					n = &memberNode{base{pt.pos}, n, from, optional, false}
					p.expect(tBracket, "]")
				}
			}
		} else {
			break
		}
		pt = p.cur
	}
	return n
}

func isIdentWord(s string) bool {
	if s == "" {
		return false
	}
	for _, r := range s {
		if !(r == '_' || r == '$' || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9')) {
			return false
		}
	}
	return true
}
EOF
echo ok

