package main

import "fmt"

type xt int

const (
	xUnknown xt = iota
	xInt
	xFloat
	xString
	xBool
	xNil
	xArray
	xMap
	xTime
	xDuration
)

func (t xt) String() string {
	switch t {
	case xInt:
		return "int"
	case xFloat:
		return "float64"
	case xString:
		return "string"
	case xBool:
		return "bool"
	case xNil:
		return "nil"
	case xArray:
		return "[]interface {}"
	case xMap:
		return "map[string]interface {}"
	case xTime:
		return "time.Time"
	case xDuration:
		return "time.Duration"
	}
	return "interface {}"
}

func isNum(t xt) bool { return t == xInt || t == xFloat }

type funcSig struct {
	params   []xt
	variadic bool
	ret      xt
}

var walkFuncs = map[string]funcSig{
	"Size":     {ret: xString},
	"Mode":     {ret: xString},
	"ModTime":  {ret: xString},
	"Owner":    {ret: xString},
	"PadLeft":  {params: []xt{xString, xInt}, ret: xString},
	"PadRight": {params: []xt{xString, xInt}, ret: xString},
	"Sprintf":  {params: []xt{xString}, variadic: true, ret: xString},
}

var builtinRet = map[string]xt{
	"len": xInt, "abs": xUnknown, "ceil": xFloat, "floor": xFloat, "round": xFloat,
	"int": xInt, "float": xFloat, "string": xString, "trim": xString, "trimPrefix": xString,
	"trimSuffix": xString, "upper": xString, "lower": xString, "split": xArray, "splitAfter": xArray,
	"replace": xString, "repeat": xString, "join": xString, "indexOf": xInt, "lastIndexOf": xInt,
	"hasPrefix": xBool, "hasSuffix": xBool, "max": xUnknown, "min": xUnknown, "sum": xUnknown,
	"mean": xFloat, "median": xFloat, "first": xUnknown, "last": xUnknown, "take": xArray,
	"keys": xArray, "values": xArray, "toJSON": xString, "fromJSON": xUnknown, "toBase64": xString,
	"fromBase64": xString, "now": xTime, "duration": xDuration, "date": xTime, "timezone": xUnknown,
	"reverse": xArray, "uniq": xArray, "sort": xArray, "sortBy": xArray, "concat": xArray,
	"flatten": xArray, "toPairs": xArray, "fromPairs": xMap, "get": xUnknown, "type": xString,
	"all": xBool, "none": xBool, "any": xBool, "one": xBool, "filter": xArray, "map": xArray,
	"count": xInt, "find": xUnknown, "findIndex": xInt, "findLast": xUnknown, "findLastIndex": xInt,
	"groupBy": xMap, "reduce": xUnknown, "bitand": xInt, "bitor": xInt, "bitxor": xInt,
	"bitnand": xInt, "bitnot": xInt, "bitshl": xInt, "bitshr": xInt, "bitushr": xInt,
}

type checker struct {
	src  string
	vars map[string]xt
	err  error
}

func (c *checker) fail(n node, format string, a ...interface{}) xt {
	if c.err == nil {
		c.err = &exprError{msg: fmt.Sprintf(format, a...), pos: n.position(), source: c.src}
	}
	return xUnknown
}

func assignable(arg, param xt) bool {
	if arg == xUnknown || param == xUnknown {
		return true
	}
	if arg == param {
		return true
	}
	if arg == xNil {
		return param == xArray || param == xMap
	}
	return false
}

func (c *checker) check(n node) xt {
	if c.err != nil {
		return xUnknown
	}
	switch n := n.(type) {
	case *nilNode:
		return xNil
	case *boolNode:
		return xBool
	case *intNode:
		return xInt
	case *floatNode:
		return xFloat
	case *stringNode:
		return xString
	case *identNode:
		if t, ok := c.vars[n.name]; ok {
			return t
		}
		switch n.name {
		case "current_file":
			return xUnknown
		case "files":
			return xArray
		}
		if _, ok := walkFuncs[n.name]; ok {
			return xUnknown
		}
		return c.fail(n, "unknown name %v", n.name)
	case *pointerNode:
		return xUnknown
	case *arrayNode:
		for _, it := range n.items {
			c.check(it)
		}
		return xArray
	case *mapNode:
		for i := range n.keys {
			c.check(n.keys[i])
			c.check(n.values[i])
		}
		return xMap
	case *memberNode:
		c.check(n.obj)
		if _, ok := n.prop.(*stringNode); !ok || n.method {
			c.check(n.prop)
		}
		return xUnknown
	case *chainNode:
		return c.check(n.x)
	case *sliceNode:
		t := c.check(n.obj)
		if n.from != nil {
			c.check(n.from)
		}
		if n.to != nil {
			c.check(n.to)
		}
		if t == xString || t == xArray {
			return t
		}
		return xUnknown
	case *closureNode:
		c.check(n.body)
		return xUnknown
	case *callNode:
		if mn, ok := n.callee.(*memberNode); ok {
			c.check(mn.obj)
			for _, a := range n.args {
				c.check(a)
			}
			return xUnknown
		}
		id := n.callee.(*identNode)
		if sig, ok := walkFuncs[id.name]; ok {
			if !sig.variadic && len(n.args) > len(sig.params) {
				return c.fail(n, "too many arguments to call %v", id.name)
			}
			if len(n.args) < len(sig.params) {
				return c.fail(n, "not enough arguments to call %v", id.name)
			}
			for i, a := range n.args {
				at := c.check(a)
				if c.err != nil {
					return xUnknown
				}
				if i < len(sig.params) && !assignable(at, sig.params[i]) {
					return c.fail(a, "cannot use %v as argument (type %v) to call %v ", at, sig.params[i], id.name)
				}
			}
			return sig.ret
		}
		if rt, ok := builtinRet[id.name]; ok {
			var first xt
			for i, a := range n.args {
				t := c.check(a)
				if i == 0 {
					first = t
				}
			}
			switch id.name {
			case "abs", "max", "min":
				if isNum(first) {
					return first
				}
			case "reverse", "uniq", "sort", "take":
				return xArray
			}
			return rt
		}
		return c.fail(n, "unknown name %v", id.name)
	case *unaryNode:
		t := c.check(n.x)
		switch n.op {
		case "not", "!":
			if t == xBool || t == xUnknown {
				return xBool
			}
			return c.fail(n, "invalid operation: %v (mismatched type %v)", n.op, t)
		case "-", "+":
			if isNum(t) || t == xUnknown {
				return t
			}
			return c.fail(n, "invalid operation: %v (mismatched type %v)", n.op, t)
		}
		return xUnknown
	case *binaryNode:
		l := c.check(n.left)
		r := c.check(n.right)
		if c.err != nil {
			return xUnknown
		}
		mismatch := func() xt {
			return c.fail(n, "invalid operation: %v (mismatched types %v and %v)", n.op, l, r)
		}
		unk := l == xUnknown || r == xUnknown
		switch n.op {
		case "==", "!=":
			return xBool
		case "or", "||", "and", "&&":
			if (l == xBool || l == xUnknown) && (r == xBool || r == xUnknown) {
				return xBool
			}
			return mismatch()
		case "<", ">", "<=", ">=":
			if unk || (isNum(l) && isNum(r)) || (l == xString && r == xString) || (l == xTime && r == xTime) || (l == xDuration && r == xDuration) {
				return xBool
			}
			return mismatch()
		case "+":
			if l == xInt && r == xInt {
				return xInt
			}
			if isNum(l) && isNum(r) {
				return xFloat
			}
			if l == xString && r == xString {
				return xString
			}
			if (l == xTime && r == xDuration) || (l == xDuration && r == xTime) {
				return xTime
			}
			if l == xDuration && r == xDuration {
				return xDuration
			}
			if unk {
				return xUnknown
			}
			return mismatch()
		case "-":
			if l == xInt && r == xInt {
				return xInt
			}
			if isNum(l) && isNum(r) {
				return xFloat
			}
			if l == xTime && r == xTime {
				return xDuration
			}
			if l == xTime && r == xDuration {
				return xTime
			}
			if unk {
				return xUnknown
			}
			return mismatch()
		case "*":
			if l == xInt && r == xInt {
				return xInt
			}
			if isNum(l) && isNum(r) {
				return xFloat
			}
			if unk {
				return xUnknown
			}
			return mismatch()
		case "/", "**", "^":
			if isNum(l) && isNum(r) {
				return xFloat
			}
			if unk {
				return xFloat
			}
			return mismatch()
		case "%":
			if l == xInt && r == xInt {
				return xInt
			}
			if unk && (l == xInt || l == xUnknown) && (r == xInt || r == xUnknown) {
				return xInt
			}
			return mismatch()
		case "in":
			if r == xArray || r == xMap || r == xUnknown {
				return xBool
			}
			return mismatch()
		case "matches", "contains", "startsWith", "endsWith":
			if (l == xString || l == xUnknown) && (r == xString || r == xUnknown) {
				return xBool
			}
			return mismatch()
		case "..":
			if (l == xInt || l == xUnknown) && (r == xInt || r == xUnknown) {
				return xArray
			}
			return mismatch()
		case "??":
			if l == xNil {
				return r
			}
			return xUnknown
		}
		return xUnknown
	case *condNode:
		ct := c.check(n.cond)
		if ct != xBool && ct != xUnknown {
			return c.fail(n.cond, "non-bool expression (type %v) used as condition", ct)
		}
		a := c.check(n.a)
		b := c.check(n.b)
		if a == b {
			return a
		}
		return xUnknown
	case *letNode:
		t := c.check(n.value)
		old, had := c.vars[n.name]
		c.vars[n.name] = t
		r := c.check(n.expr)
		if had {
			c.vars[n.name] = old
		} else {
			delete(c.vars, n.name)
		}
		return r
	case *seqNode:
		var t xt
		for _, x := range n.nodes {
			t = c.check(x)
		}
		return t
	}
	return xUnknown
}
