func (e *evaluator) eval(n node) interface{} {
	switch n := n.(type) {
	case *nilNode:
		return nil
	case *boolNode:
		return n.v
	case *intNode:
		return n.v
	case *floatNode:
		return n.v
	case *stringNode:
		return n.v
	case *identNode:
		if v, ok := e.vars[n.name]; ok {
			return v
		}
		if v, ok := e.env[n.name]; ok {
			return v
		}
		return nil
	case *pointerNode:
		if len(e.ptrs) == 0 {
			return nil
		}
		cur := e.ptrs[len(e.ptrs)-1]
		if n.name != "" {
			if m, ok := cur.(map[string]interface{}); ok {
				return m[n.name]
			}
		}
		return cur
	case *arrayNode:
		out := make([]interface{}, len(n.items))
		for i, it := range n.items {
			out[i] = e.eval(it)
		}
		return out
	case *mapNode:
		out := map[string]interface{}{}
		for i := range n.keys {
			k := e.eval(n.keys[i])
			out[fmt.Sprint(k)] = e.eval(n.values[i])
		}
		return out
	case *chainNode:
		return e.eval(n.x)
	case *memberNode:
		obj := e.eval(n.obj)
		return e.member(n, obj, n.prop, n.optional)
	case *sliceNode:
		obj := e.eval(n.obj)
		var from, to interface{}
		if n.from != nil {
