			if to != nil {
				b = toInt(to)
			}
			if a < 0 {
				a += l
			}
			if b < 0 {
				b += l
			}
			a = max(0, min(a, l))
			b = max(a, min(b, l))
			return s[a:b]
		}
		if sl, ok := toSlice(obj); ok {
			l := len(sl)
			a, b := 0, l
			if from != nil {
				a = toInt(from)
			}
			if to != nil {
				b = toInt(to)
			}
			if a < 0 {
				a += l
			}
			if b < 0 {
				b += l
			}
			a = max(0, min(a, l))
			b = max(a, min(b, l))
			return sl[a:b]
		}
		e.fail(n, "cannot slice %v", typeName(obj))
	case *unaryNode:
		v := e.eval(n.x)
		switch n.op {
		case "not", "!":
			return !truthy(v)
