				return -toInt(v)
			}
			return -toFloat(v)
		case "+":
			return v
		}
	case *binaryNode:
		return e.binary(n)
	case *condNode:
		if truthy(e.eval(n.cond)) {
			return e.eval(n.a)
		}
		return e.eval(n.b)
