}

func (e *evaluator) member(n node, obj interface{}, propNode node, optional bool) interface{} {
	var prop interface{}
	if s, ok := propNode.(*stringNode); ok {
		prop = s.v
	} else {
		prop = e.eval(propNode)
	}
	if obj == nil {
		if optional {
			return nil
		}
		e.fail(n, "cannot fetch %v from %v", prop, typeName(obj))
	}
	switch o := obj.(type) {
	case map[string]interface{}:
		return o[fmt.Sprint(prop)]
	case string:
		if isIntVal(prop) {
			rs := []rune(o)
			i := toInt(prop)
			if i < 0 {
				i += len(rs)
			}
			if i < 0 || i >= len(rs) {
				e.fail(n, "index out of range: %v (array length is %v)", toInt(prop), len(rs))
			}
			return string(rs[i])
		}
	}
	if sl, ok := toSlice(obj); ok && isIntVal(prop) {
		i := toInt(prop)
		if i < 0 {
			i += len(sl)
		}
		if i < 0 || i >= len(sl) {
			e.fail(n, "index out of range: %v (array length is %v)", toInt(prop), len(sl))
		}
		return sl[i]
	}
	name, isStr := prop.(string)
	rv := reflect.ValueOf(obj)
	if isStr {
		if rv.Kind() == reflect.Map {
			v := rv.MapIndex(reflect.ValueOf(name))
			if v.IsValid() {
				return v.Interface()
			}
			return nil
		}
		if m := rv.MethodByName(name); m.IsValid() {
			return m.Interface()
		}
		ev := rv
		for ev.Kind() == reflect.Ptr || ev.Kind() == reflect.Interface {
			if ev.IsNil() {
				break
			}
			ev = ev.Elem()
		}
		if ev.Kind() == reflect.Struct {
			if f := ev.FieldByName(name); f.IsValid() && f.CanInterface() {
				return f.Interface()
			}
		}
	}
	e.fail(n, "cannot fetch %v from %v", prop, typeName(obj))
	return nil
}

func (e *evaluator) binary(n *binaryNode) interface{} {
	switch n.op {
	case "or", "||":
		if truthy(e.eval(n.left)) {
			return true
		}
		return truthy(e.eval(n.right))
	case "and", "&&":
		if !truthy(e.eval(n.left)) {
			return false
		}
		return truthy(e.eval(n.right))
