		}
	case "..":
		if isIntVal(l) && isIntVal(r) {
			a, b := toInt(l), toInt(r)
			out := []interface{}{}
			for i := a; i <= b; i++ {
				out = append(out, i)
			}
			return out
		}
	}
	e.fail(n, "invalid operation: %v (mismatched types %v and %v)", n.op, typeName(l), typeName(r))
	return nil
}

func cmpInt(a, b int) int {
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}

func isString(v interface{}) bool {
	_, ok := v.(string)
	return ok
}

func (e *evaluator) withPtr(v interface{}, f func() interface{}) interface{} {
	e.ptrs = append(e.ptrs, v)
	defer func() { e.ptrs = e.ptrs[:len(e.ptrs)-1] }()
	return f()
}

func (e *evaluator) call(n *callNode) interface{} {
	if mn, ok := n.callee.(*memberNode); ok {
		obj := e.eval(mn.obj)
		if obj == nil && mn.optional {
			return nil
		}
		name := mn.prop.(*stringNode).v
		if obj == nil {
			e.fail(mn, "cannot fetch %v from %v", name, typeName(obj))
		}
		m := reflect.ValueOf(obj).MethodByName(name)
		if !m.IsValid() {
			if mp, ok := obj.(map[string]interface{}); ok {
				if fn, ok := mp[name].(func(...interface{}) interface{}); ok {
					args := make([]interface{}, len(n.args))
					for i, a := range n.args {
						args[i] = e.eval(a)
					}
					return fn(args...)
				}
			}
			e.fail(mn, "cannot fetch %v from %v", name, typeName(obj))
		}
		args := make([]reflect.Value, len(n.args))
		mt := m.Type()
		for i, a := range n.args {
			v := e.eval(a)
			if v == nil {
				if i < mt.NumIn() {
					args[i] = reflect.Zero(mt.In(i))
				} else {
					args[i] = reflect.ValueOf(&v).Elem()
				}
				continue
			}
			rv := reflect.ValueOf(v)
			if i < mt.NumIn() && !mt.IsVariadic() && rv.Type().ConvertibleTo(mt.In(i)) {
				rv = rv.Convert(mt.In(i))
			}
			args[i] = rv
		}
		if !mt.IsVariadic() && len(args) != mt.NumIn() {
			e.fail(mn, "invalid number of arguments (expected %d, got %d)", mt.NumIn(), len(args))
		}
		out := m.Call(args)
		if len(out) == 0 {
			return nil
		}
		if len(out) == 2 {
			if errv, ok := out[1].Interface().(error); ok && errv != nil {
				e.fail(mn, "%v", errv)
			}
		}
		return out[0].Interface()
	}
	id := n.callee.(*identNode)
	if fn, ok := e.funcs[id.name]; ok {
		args := make([]interface{}, len(n.args))
		for i, a := range n.args {
			args[i] = e.eval(a)
		}
		return fn(args)
	}
	return e.builtin(n, id.name)
}

func (e *evaluator) argVals(n *callNode) []interface{} {
	args := make([]interface{}, len(n.args))
	for i, a := range n.args {
		if _, ok := a.(*closureNode); ok {
			continue
		}
		args[i] = e.eval(a)
	}
	return args
}

func (e *evaluator) builtin(n *callNode, name string) interface{} {
	if _, ok := predicateBuiltins[name]; ok {
		return e.predicate(n, name)
	}
	a := e.argVals(n)
	arg := func(i int) interface{} {
		if i < len(a) {
			return a[i]
		}
		return nil
	}
	str := func(i int) string {
		s, _ := arg(i).(string)
		return s
	}
	switch name {
	case "len":
		v := arg(0)
		if s, ok := v.(string); ok {
			return len(s)
		}
		if m, ok := v.(map[string]interface{}); ok {
			return len(m)
		}
		if sl, ok := toSlice(v); ok {
			return len(sl)
		}
		e.fail(n, "invalid argument for len (type %v)", typeName(v))
	case "abs":
		v := arg(0)
		if isIntVal(v) {
			x := toInt(v)
			if x < 0 {
				x = -x
			}
			return x
		}
		return math.Abs(toFloat(v))
	case "ceil":
		return math.Ceil(toFloat(arg(0)))
	case "floor":
		return math.Floor(toFloat(arg(0)))
	case "round":
		return math.Round(toFloat(arg(0)))
	case "int":
		v := arg(0)
		if isNumVal(v) {
			return toInt(v)
		}
		if s, ok := v.(string); ok {
			var x int
			if _, err := fmt.Sscanf(s, "%d", &x); err == nil && fmt.Sprint(x) == strings.TrimSpace(s) {
				return x
			}
		}
		e.fail(n, "invalid operation: int(%v)", v)
	case "float":
		v := arg(0)
		if isNumVal(v) {
			return toFloat(v)
		}
		if s, ok := v.(string); ok {
			var x float64
			if _, err := fmt.Sscanf(s, "%g", &x); err == nil {
				return x
			}
		}
		e.fail(n, "invalid operation: float(%v)", v)
	case "string":
		return fmt.Sprint(arg(0))
	case "trim":
		if len(a) > 1 {
			return strings.Trim(str(0), str(1))
		}
		return strings.TrimSpace(str(0))
	case "trimPrefix":
		p := " "
		if len(a) > 1 {
			p = str(1)
		}
		return strings.TrimPrefix(str(0), p)
	case "trimSuffix":
		p := " "
		if len(a) > 1 {
			p = str(1)
		}
		return strings.TrimSuffix(str(0), p)
	case "upper":
		return strings.ToUpper(str(0))
	case "lower":
		return strings.ToLower(str(0))
	case "split":
		var parts []string
		if len(a) > 2 {
			parts = strings.SplitN(str(0), str(1), toInt(arg(2)))
		} else {
			parts = strings.Split(str(0), str(1))
		}
		out := make([]interface{}, len(parts))
		for i, p := range parts {
			out[i] = p
		}
		return out
	case "splitAfter":
		parts := strings.SplitAfter(str(0), str(1))
		out := make([]interface{}, len(parts))
		for i, p := range parts {
			out[i] = p
		}
		return out
	case "replace":
		return strings.ReplaceAll(str(0), str(1), str(2))
	case "repeat":
		c := toInt(arg(1))
		if c < 0 {
			e.fail(n, "invalid argument for repeat (count must be non-negative)")
		}
		return strings.Repeat(str(0), c)
	case "join":
		sl, _ := toSlice(arg(0))
		sep := ""
		if len(a) > 1 {
			sep = str(1)
		}
		parts := make([]string, len(sl))
		for i, x := range sl {
			s, ok := x.(string)
			if !ok {
				e.fail(n, "invalid argument for join (type %v)", typeName(x))
			}
			parts[i] = s
		}
		return strings.Join(parts, sep)
	case "indexOf":
		return strings.Index(str(0), str(1))
	case "lastIndexOf":
		return strings.LastIndex(str(0), str(1))
	case "hasPrefix":
		return strings.HasPrefix(str(0), str(1))
	case "hasSuffix":
		return strings.HasSuffix(str(0), str(1))
	case "max", "min":
		vals := a
		if len(a) == 1 {
			if sl, ok := toSlice(a[0]); ok {
				vals = sl
			}
		}
		if len(vals) == 0 {
			return nil
		}
		best := vals[0]
		for _, v := range vals[1:] {
			if (name == "max" && toFloat(v) > toFloat(best)) || (name == "min" && toFloat(v) < toFloat(best)) {
				best = v
			}
		}
		return best
	case "sum":
		sl, _ := toSlice(arg(0))
		allInt := true
		var fi int
		var ff float64
		for _, v := range sl {
			if isIntVal(v) {
				fi += toInt(v)
			} else {
				allInt = false
			}
			ff += toFloat(v)
		}
		if allInt {
			return fi
		}
		return ff
	case "mean":
		sl, _ := toSlice(arg(0))
		if len(sl) == 0 {
			return 0.0
		}
		var s float64
		for _, v := range sl {
			s += toFloat(v)
		}
		return s / float64(len(sl))
	case "median":
		sl, _ := toSlice(arg(0))
		if len(sl) == 0 {
			return 0.0
		}
		fs := make([]float64, len(sl))
		for i, v := range sl {
			fs[i] = toFloat(v)
		}
		sort.Float64s(fs)
		if len(fs)%2 == 0 {
			return (fs[len(fs)/2-1] + fs[len(fs)/2]) / 2
		}
		return fs[len(fs)/2]
	case "first":
		sl, _ := toSlice(arg(0))
		if len(sl) == 0 {
			return nil
		}
		return sl[0]
	case "last":
		sl, _ := toSlice(arg(0))
		if len(sl) == 0 {
			return nil
		}
		return sl[len(sl)-1]
	case "take":
		sl, _ := toSlice(arg(0))
		k := toInt(arg(1))
		if k > len(sl) {
			k = len(sl)
		}
		if k < 0 {
			k = 0
		}
		return sl[:k]
	case "keys", "values":
		m, _ := arg(0).(map[string]interface{})
		ks := make([]string, 0, len(m))
		for k := range m {
			ks = append(ks, k)
		}
		sort.Strings(ks)
		out := make([]interface{}, len(ks))
		for i, k := range ks {
			if name == "keys" {
				out[i] = k
			} else {
				out[i] = m[k]
			}
		}
		return out
	case "toJSON":
		b, err := json.MarshalIndent(arg(0), "", "  ")
		if err != nil {
			e.fail(n, "%v", err)
		}
		return string(b)
	case "fromJSON":
		var v interface{}
		if err := json.Unmarshal([]byte(str(0)), &v); err != nil {
			e.fail(n, "%v", err)
		}
		return v
	case "toBase64":
		return base64.StdEncoding.EncodeToString([]byte(str(0)))
	case "fromBase64":
		b, err := base64.StdEncoding.DecodeString(str(0))
		if err != nil {
			e.fail(n, "%v", err)
		}
		return string(b)
	case "now":
		return time.Now()
	case "duration":
		d, err := time.ParseDuration(str(0))
		if err != nil {
			e.fail(n, "%v", err)
		}
		return d
	case "date":
		s := str(0)
		if len(a) > 1 {
			t, err := time.Parse(str(1), s)
			if err != nil {
				e.fail(n, "%v", err)
			}
			return t
		}
		layouts := []string{"2006-01-02", "15:04:05", "2006-01-02 15:04:05", time.RFC3339, time.RFC822, time.RFC850, time.RFC1123, time.RFC3339Nano, time.ANSIC, time.UnixDate, time.RubyDate, time.Kitchen}
		for _, l := range layouts {
			if t, err := time.Parse(l, s); err == nil {
				return t
			}
		}
		e.fail(n, "invalid date %v", s)
	case "reverse":
		sl, _ := toSlice(arg(0))
		out := make([]interface{}, len(sl))
		for i, v := range sl {
			out[len(sl)-1-i] = v
		}
		return out
	case "uniq":
		sl, _ := toSlice(arg(0))
		var out []interface{}
		for _, v := range sl {
			found := false
			for _, o := range out {
				if valuesEqual(o, v) {
					found = true
					break
				}
			}
			if !found {
				out = append(out, v)
			}
		}
		return out
	case "sort":
		sl, _ := toSlice(arg(0))
		out := append([]interface{}{}, sl...)
		desc := len(a) > 1 && str(1) == "desc"
		sort.SliceStable(out, func(i, j int) bool {
			x, y := out[i], out[j]
			var less bool
			if isString(x) && isString(y) {
				less = x.(string) < y.(string)
			} else {
				less = toFloat(x) < toFloat(y)
			}
			if desc {
				if isString(x) && isString(y) {
					return x.(string) > y.(string)
				}
				return toFloat(x) > toFloat(y)
			}
			return less
		})
		return out
	case "concat":
		var out []interface{}
		for _, v := range a {
			sl, _ := toSlice(v)
			out = append(out, sl...)
		}
		return out
	case "flatten":
		var out []interface{}
		var rec func(v interface{})
		rec = func(v interface{}) {
			if sl, ok := toSlice(v); ok {
				for _, x := range sl {
					rec(x)
				}
				return
			}
			out = append(out, v)
		}
		sl, _ := toSlice(arg(0))
		for _, x := range sl {
			rec(x)
		}
		return out
	case "get":
		obj := arg(0)
		key := arg(1)
		if m, ok := obj.(map[string]interface{}); ok {
			return m[fmt.Sprint(key)]
		}
		if sl, ok := toSlice(obj); ok && isIntVal(key) {
			i := toInt(key)
			if i < 0 {
				i += len(sl)
			}
			if i >= 0 && i < len(sl) {
				return sl[i]
			}
		}
		return nil
	case "type":
		v := arg(0)
		switch v.(type) {
		case nil:
			return "nil"
		case bool:
			return "bool"
		case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64:
			return "int"
		case float32, float64:
			return "float"
		case string:
			return "string"
		case []interface{}:
			return "array"
		case map[string]interface{}:
			return "map"
		case time.Time:
			return "time"
		case time.Duration:
			return "duration"
		}
		if _, ok := toSlice(v); ok {
			return "array"
		}
		return reflect.TypeOf(v).String()
	case "toPairs":
		m, _ := arg(0).(map[string]interface{})
		ks := make([]string, 0, len(m))
		for k := range m {
			ks = append(ks, k)
		}
		sort.Strings(ks)
		out := make([]interface{}, len(ks))
		for i, k := range ks {
			out[i] = []interface{}{k, m[k]}
		}
		return out
	case "fromPairs":
		sl, _ := toSlice(arg(0))
		out := map[string]interface{}{}
		for _, p := range sl {
			pp, _ := toSlice(p)
			if len(pp) == 2 {
				out[fmt.Sprint(pp[0])] = pp[1]
			}
		}
		return out
	case "bitand":
		return toInt(arg(0)) & toInt(arg(1))
	case "bitor":
		return toInt(arg(0)) | toInt(arg(1))
	case "bitxor":
		return toInt(arg(0)) ^ toInt(arg(1))
	case "bitnand":
		return toInt(arg(0)) &^ toInt(arg(1))
	case "bitnot":
		return ^toInt(arg(0))
	case "bitshl":
		return toInt(arg(0)) << uint(toInt(arg(1)))
	case "bitshr":
		return toInt(arg(0)) >> uint(toInt(arg(1)))
	case "bitushr":
		return int(uint(toInt(arg(0))) >> uint(toInt(arg(1))))
	case "timezone":
		loc, err := time.LoadLocation(str(0))
		if err != nil {
			e.fail(n, "%v", err)
		}
		return loc
	}
	e.fail(n, "unknown name %v", name)
	return nil
}

func (e *evaluator) predicate(n *callNode, name string) interface{} {
	coll := e.eval(n.args[0])
	var body node
	if cl, ok := n.args[1].(*closureNode); ok {
		body = cl.body
	}
	sl, ok := toSlice(coll)
	if !ok {
		if coll == nil {
			sl = nil
		} else {
			e.fail(n, "cannot iterate over %v", typeName(coll))
		}
	}
	run := func(v interface{}) interface{} {
		return e.withPtr(v, func() interface{} { return e.eval(body) })
	}
	switch name {
	case "all":
		for _, v := range sl {
			if !truthy(run(v)) {
				return false
			}
		}
		return true
	case "any":
		for _, v := range sl {
			if truthy(run(v)) {
				return true
			}
		}
		return false
	case "none":
		for _, v := range sl {
			if truthy(run(v)) {
				return false
			}
		}
		return true
	case "one":
		c := 0
		for _, v := range sl {
			if truthy(run(v)) {
				c++
			}
		}
		return c == 1
	case "filter":
		out := []interface{}{}
		for _, v := range sl {
			if truthy(run(v)) {
				out = append(out, v)
			}
		}
		return out
	case "map":
		out := make([]interface{}, 0, len(sl))
		for _, v := range sl {
			out = append(out, run(v))
		}
		return out
	case "count":
		c := 0
		for _, v := range sl {
			if truthy(run(v)) {
				c++
			}
		}
		return c
	case "sum":
		allInt := true
		var si int
		var sf float64
		for _, v := range sl {
			r := run(v)
			if isIntVal(r) {
				si += toInt(r)
			} else {
				allInt = false
			}
			sf += toFloat(r)
		}
		if allInt {
			return si
		}
		return sf
	case "find":
		for _, v := range sl {
			if truthy(run(v)) {
				return v
			}
		}
		return nil
	case "findIndex":
		for i, v := range sl {
			if truthy(run(v)) {
				return i
			}
		}
		return -1
	case "findLast":
		for i := len(sl) - 1; i >= 0; i-- {
			if truthy(run(sl[i])) {
				return sl[i]
			}
		}
		return nil
	case "findLastIndex":
		for i := len(sl) - 1; i >= 0; i-- {
			if truthy(run(sl[i])) {
				return i
			}
		}
		return -1
	case "groupBy":
		out := map[string]interface{}{}
		for _, v := range sl {
			k := fmt.Sprint(run(v))
			lst, _ := out[k].([]interface{})
			out[k] = append(lst, v)
		}
		return out
	case "sortBy":
		out := append([]interface{}{}, sl...)
		keys := make([]interface{}, len(out))
		for i, v := range out {
			keys[i] = run(v)
		}
		idx := make([]int, len(out))
		for i := range idx {
			idx[i] = i
		}
		desc := len(n.args) > 2 && fmt.Sprint(e.eval(n.args[2])) == "desc"
		sort.SliceStable(idx, func(i, j int) bool {
			x, y := keys[idx[i]], keys[idx[j]]
			var less bool
			if isString(x) && isString(y) {
				less = x.(string) < y.(string)
				if desc {
					less = x.(string) > y.(string)
				}
			} else {
				less = toFloat(x) < toFloat(y)
				if desc {
					less = toFloat(x) > toFloat(y)
				}
			}
			return less
		})
		res := make([]interface{}, len(out))
		for i, k := range idx {
			res[i] = out[k]
		}
		return res
	case "reduce":
		var acc interface{}
		start := 0
		if len(n.args) > 2 {
			acc = e.eval(n.args[2])
		} else if len(sl) > 0 {
			acc = sl[0]
			start = 1
		}
		for i := start; i < len(sl); i++ {
			v := sl[i]
			old, had := e.vars["#acc"]
			e.vars["#acc"] = acc
			acc = e.withPtr(v, func() interface{} {
				e.vars["acc"] = acc
				return e.eval(body)
			})
			if had {
				e.vars["#acc"] = old
			}
		}
		delete(e.vars, "acc")
		return acc
	}
	return nil
}
EOF
echo ok"}

