cd /workspace && cat > expr_eval.go <<'EOF'
package main

import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"math"
	"reflect"
	"regexp"
	"sort"
	"strings"
	"time"
)

type evalPanic struct{ err error }

type evaluator struct {
	src    string
	env    map[string]interface{}
	funcs  map[string]func(args []interface{}) interface{}
	vars   map[string]interface{}
	ptrs   []interface{}
}

func (e *evaluator) fail(n node, format string, a ...interface{}) {
	panic(evalPanic{&exprError{msg: fmt.Sprintf(format, a...), pos: n.position(), source: e.src}})
}

func isIntVal(v interface{}) bool {
	switch v.(type) {
	case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64:
		return true
	}
	return false
}

func isNumVal(v interface{}) bool {
	switch v.(type) {
	case float32, float64:
		return true
	}
	return isIntVal(v)
}

func toInt(v interface{}) int {
	switch x := v.(type) {
	case int:
		return x
	case int8:
		return int(x)
	case int16:
		return int(x)
	case int32:
		return int(x)
	case int64:
		return int(x)
	case uint:
		return int(x)
	case uint8:
		return int(x)
	case uint16:
		return int(x)
	case uint32:
		return int(x)
	case uint64:
		return int(x)
	case float32:
		return int(x)
	case float64:
		return int(x)
	}
	return 0
}

func toFloat(v interface{}) float64 {
	switch x := v.(type) {
	case float32:
		return float64(x)
	case float64:
		return x
	}
	return float64(toInt(v))
}

func typeName(v interface{}) string {
	if v == nil {
		return "nil"
	}
	return reflect.TypeOf(v).String()
}

func toSlice(v interface{}) ([]interface{}, bool) {
	if v == nil {
		return nil, false
	}
	if s, ok := v.([]interface{}); ok {
		return s, true
	}
	rv := reflect.ValueOf(v)
	if rv.Kind() == reflect.Slice || rv.Kind() == reflect.Array {
		out := make([]interface{}, rv.Len())
		for i := 0; i < rv.Len(); i++ {
			out[i] = rv.Index(i).Interface()
		}
		return out, true
	}
	return nil, false
}

func valuesEqual(a, b interface{}) bool {
	if isNumVal(a) && isNumVal(b) {
		if isIntVal(a) && isIntVal(b) {
			return toInt(a) == toInt(b)
		}
		return toFloat(a) == toFloat(b)
	}
	if a == nil || b == nil {
		if a == nil && b == nil {
			return true
		}
		rv := reflect.ValueOf(a)
		if a == nil {
			rv = reflect.ValueOf(b)
		}
		switch rv.Kind() {
		case reflect.Ptr, reflect.Map, reflect.Slice, reflect.Interface, reflect.Func:
			return rv.IsNil()
		}
		return false
	}
	if ta, ok := a.(time.Time); ok {
		if tb, ok := b.(time.Time); ok {
			return ta.Equal(tb)
		}
	}
	return reflect.DeepEqual(a, b)
}

func truthy(v interface{}) bool {
	b, _ := v.(bool)
	return b
}

func (e *evaluator) eval(n node) interface{} {
	switch n := n.(type) {
	case *nilNode:
		return nil
	case *boolNode:
		return n.v
	case *intNode:
		return n.v
	case *floatNode:
		return n.v
	case *stringNode:
		return n.v
	case *identNode:
		if v, ok := e.vars[n.name]; ok {
			return v
		}
		if v, ok := e.env[n.name]; ok {
			return v
		}
		return nil
	case *pointerNode:
		if len(e.ptrs) == 0 {
			return nil
		}
		cur := e.ptrs[len(e.ptrs)-1]
		if n.name != "" {
			if m, ok := cur.(map[string]interface{}); ok {
				return m[n.name]
			}
		}
		return cur
	case *arrayNode:
		out := make([]interface{}, len(n.items))
		for i, it := range n.items {
			out[i] = e.eval(it)
		}
		return out
	case *mapNode:
		out := map[string]interface{}{}
		for i := range n.keys {
			k := e.eval(n.keys[i])
			out[fmt.Sprint(k)] = e.eval(n.values[i])
		}
		return out
	case *chainNode:
		return e.eval(n.x)
	case *memberNode:
		obj := e.eval(n.obj)
		return e.member(n, obj, n.prop, n.optional)
	case *sliceNode:
		obj := e.eval(n.obj)
		var from, to interface{}
		if n.from != nil {
			from = e.eval(n.from)
		}
		if n.to != nil {
			to = e.eval(n.to)
		}
		if s, ok := obj.(string); ok {
			l := len(s)
			a, b := 0, l
			if from != nil {
				a = toInt(from)
			}
			if to != nil {
				b = toInt(to)
			}
			if a < 0 {
				a += l
			}
			if b < 0 {
				b += l
			}
			a = max(0, min(a, l))
			b = max(a, min(b, l))
			return s[a:b]
		}
		if sl, ok := toSlice(obj); ok {
			l := len(sl)
			a, b := 0, l
			if from != nil {
				a = toInt(from)
			}
			if to != nil {
				b = toInt(to)
			}
			if a < 0 {
				a += l
			}
			if b < 0 {
				b += l
			}
			a = max(0, min(a, l))
			b = max(a, min(b, l))
			return sl[a:b]
		}
		e.fail(n, "cannot slice %v", typeName(obj))
	case *unaryNode:
		v := e.eval(n.x)
		switch n.op {
		case "not", "!":
			return !truthy(v)
		case "-":
			if isIntVal(v) {
				return -toInt(v)
			}
			return -toFloat(v)
		case "+":
			return v
		}
	case *binaryNode:
		return e.binary(n)
	case *condNode:
		if truthy(e.eval(n.cond)) {
			return e.eval(n.a)
		}
		return e.eval(n.b)
	case *letNode:
		v := e.eval(n.value)
		old, had := e.vars[n.name]
		e.vars[n.name] = v
		r := e.eval(n.expr)
		if had {
			e.vars[n.name] = old
		} else {
			delete(e.vars, n.name)
		}
		return r
	case *seqNode:
		var r interface{}
		for _, x := range n.nodes {
			r = e.eval(x)
		}
		return r
	case *callNode:
		return e.call(n)
	}
	return nil
}

func (e *evaluator) member(n node, obj interface{}, propNode node, optional bool) interface{} {
	var prop interface{}
	if s, ok := propNode.(*stringNode); ok {
		prop = s.v
	} else {
		prop = e.eval(propNode)
	}
	if obj == nil {
		if optional {
			return nil
		}
		e.fail(n, "cannot fetch %v from %v", prop, typeName(obj))
	}
	switch o := obj.(type) {
	case map[string]interface{}:
		return o[fmt.Sprint(prop)]
	case string:
		if isIntVal(prop) {
			rs := []rune(o)
			i := toInt(prop)
			if i < 0 {
				i += len(rs)
			}
			if i < 0 || i >= len(rs) {
				e.fail(n, "index out of range: %v (array length is %v)", toInt(prop), len(rs))
			}
			return string(rs[i])
		}
	}
	if sl, ok := toSlice(obj); ok && isIntVal(prop) {
		i := toInt(prop)
		if i < 0 {
			i += len(sl)
		}
		if i < 0 || i >= len(sl) {
			e.fail(n, "index out of range: %v (array length is %v)", toInt(prop), len(sl))
		}
		return sl[i]
	}
	name, isStr := prop.(string)
	rv := reflect.ValueOf(obj)
	if isStr {
		if rv.Kind() == reflect.Map {
			v := rv.MapIndex(reflect.ValueOf(name))
			if v.IsValid() {
				return v.Interface()
			}
			return nil
		}
		if m := rv.MethodByName(name); m.IsValid() {
			return m.Interface()
		}
		ev := rv
		for ev.Kind() == reflect.Ptr || ev.Kind() == reflect.Interface {
			if ev.IsNil() {
				break
			}
			ev = ev.Elem()
		}
		if ev.Kind() == reflect.Struct {
			if f := ev.FieldByName(name); f.IsValid() && f.CanInterface() {
				return f.Interface()
			}
		}
	}
	e.fail(n, "cannot fetch %v from %v", prop, typeName(obj))
	return nil
}

func (e *evaluator) binary(n *binaryNode) interface{} {
	switch n.op {
	case "or", "||":
		if truthy(e.eval(n.left)) {
			return true
		}
		return truthy(e.eval(n.right))
	case "and", "&&":
		if !truthy(e.eval(n.left)) {
			return false
		}
		return truthy(e.eval(n.right))
	case "??":
		l := e.eval(n.left)
		if l == nil {
			return e.eval(n.right)
		}
		return l
	}
	l := e.eval(n.left)
	r := e.eval(n.right)
	switch n.op {
	case "==":
		return valuesEqual(l, r)
	case "!=":
		return !valuesEqual(l, r)
	case "<", ">", "<=", ">=":
		var c int
		switch {
		case isNumVal(l) && isNumVal(r):
			a, b := toFloat(l), toFloat(r)
			if isIntVal(l) && isIntVal(r) {
				ai, bi := toInt(l), toInt(r)
				c = cmpInt(ai, bi)
			} else if a < b {
				c = -1
			} else if a > b {
				c = 1
			}
		case isString(l) && isString(r):
			c = strings.Compare(l.(string), r.(string))
		default:
			if ta, ok := l.(time.Time); ok {
				if tb, ok := r.(time.Time); ok {
					if ta.Before(tb) {
						c = -1
					} else if ta.After(tb) {
						c = 1
					}
					break
				}
			}
			e.fail(n, "invalid operation: %v (mismatched types %v and %v)", n.op, typeName(l), typeName(r))
		}
		switch n.op {
		case "<":
			return c < 0
		case ">":
			return c > 0
		case "<=":
			return c <= 0
		}
		return c >= 0
	case "+":
		if isIntVal(l) && isIntVal(r) {
			return toInt(l) + toInt(r)
		}
		if isNumVal(l) && isNumVal(r) {
			return toFloat(l) + toFloat(r)
		}
		if isString(l) && isString(r) {
			return l.(string) + r.(string)
		}
		if t, ok := l.(time.Time); ok {
			if d, ok := r.(time.Duration); ok {
				return t.Add(d)
			}
		}
		if d1, ok := l.(time.Duration); ok {
			if d2, ok := r.(time.Duration); ok {
				return d1 + d2
			}
		}
	case "-":
		if isIntVal(l) && isIntVal(r) {
			return toInt(l) - toInt(r)
		}
		if isNumVal(l) && isNumVal(r) {
			return toFloat(l) - toFloat(r)
		}
		if t, ok := l.(time.Time); ok {
			if t2, ok := r.(time.Time); ok {
				return t.Sub(t2)
			}
			if d, ok := r.(time.Duration); ok {
				return t.Add(-d)
			}
		}
	case "*":
		if isIntVal(l) && isIntVal(r) {
			return toInt(l) * toInt(r)
		}
		if isNumVal(l) && isNumVal(r) {
			return toFloat(l) * toFloat(r)
		}
	case "/":
		if isNumVal(l) && isNumVal(r) {
			return toFloat(l) / toFloat(r)
		}
	case "%":
		if isIntVal(l) && isIntVal(r) {
			if toInt(r) == 0 {
				e.fail(n, "integer divide by zero")
			}
			return toInt(l) % toInt(r)
		}
	case "**", "^":
		if isNumVal(l) && isNumVal(r) {
			return math.Pow(toFloat(l), toFloat(r))
		}
	case "in":
		if m, ok := r.(map[string]interface{}); ok {
			_, has := m[fmt.Sprint(l)]
			return has
		}
		if sl, ok := toSlice(r); ok {
			for _, x := range sl {
				if valuesEqual(l, x) {
					return true
				}
			}
			return false
		}
		if r == nil {
			return false
		}
	case "contains":
		if isString(l) && isString(r) {
			return strings.Contains(l.(string), r.(string))
		}
	case "startsWith":
		if isString(l) && isString(r) {
			return strings.HasPrefix(l.(string), r.(string))
		}
	case "endsWith":
		if isString(l) && isString(r) {
			return strings.HasSuffix(l.(string), r.(string))
		}
	case "matches":
		if isString(l) && isString(r) {
			re, err := regexp.Compile(r.(string))
			if err != nil {
				e.fail(n, "%v", err)
			}
			return re.MatchString(l.(string))
		}
	case "..":
		if isIntVal(l) && isIntVal(r) {
			a, b := toInt(l), toInt(r)
			out := []interface{}{}
			for i := a; i <= b; i++ {
				out = append(out, i)
			}
			return out
		}
	}
	e.fail(n, "invalid operation: %v (mismatched types %v and %v)", n.op, typeName(l), typeName(r))
	return nil
}

func cmpInt(a, b int) int {
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}

func isString(v interface{}) bool {
	_, ok := v.(string)
	return ok
}

func (e *evaluator) withPtr(v interface{}, f func() interface{}) interface{} {
	e.ptrs = append(e.ptrs, v)
	defer func() { e.ptrs = e.ptrs[:len(e.ptrs)-1] }()
	return f()
}

func (e *evaluator) call(n *callNode) interface{} {
	if mn, ok := n.callee.(*memberNode); ok {
		obj := e.eval(mn.obj)
		if obj == nil && mn.optional {
			return nil
		}
		name := mn.prop.(*stringNode).v
		if obj == nil {
			e.fail(mn, "cannot fetch %v from %v", name, typeName(obj))
		}
		m := reflect.ValueOf(obj).MethodByName(name)
		if !m.IsValid() {
			if mp, ok := obj.(map[string]interface{}); ok {
				if fn, ok := mp[name].(func(...interface{}) interface{}); ok {
					args := make([]interface{}, len(n.args))
					for i, a := range n.args {
						args[i] = e.eval(a)
					}
					return fn(args...)
				}
			}
			e.fail(mn, "cannot fetch %v from %v", name, typeName(obj))
		}
		args := make([]reflect.Value, len(n.args))
		mt := m.Type()
		for i, a := range n.args {
			v := e.eval(a)
			if v == nil {
				if i < mt.NumIn() {
					args[i] = reflect.Zero(mt.In(i))
				} else {
					args[i] = reflect.ValueOf(&v).Elem()
				}
				continue
			}
			rv := reflect.ValueOf(v)
			if i < mt.NumIn() && !mt.IsVariadic() && rv.Type().ConvertibleTo(mt.In(i)) {
				rv = rv.Convert(mt.In(i))
			}
			args[i] = rv
		}
		if !mt.IsVariadic() && len(args) != mt.NumIn() {
			e.fail(mn, "invalid number of arguments (expected %d, got %d)", mt.NumIn(), len(args))
		}
		out := m.Call(args)
		if len(out) == 0 {
			return nil
		}
		if len(out) == 2 {
			if errv, ok := out[1].Interface().(error); ok && errv != nil {
				e.fail(mn, "%v", errv)
			}
		}
		return out[0].Interface()
	}
	id := n.callee.(*identNode)
	if fn, ok := e.funcs[id.name]; ok {
		args := make([]interface{}, len(n.args))
		for i, a := range n.args {
			args[i] = e.eval(a)
		}
		return fn(args)
	}
	return e.builtin(n, id.name)
}

func (e *evaluator) argVals(n *callNode) []interface{} {
	args := make([]interface{}, len(n.args))
	for i, a := range n.args {
		if _, ok := a.(*closureNode); ok {
			continue
		}
		args[i] = e.eval(a)
	}
	return args
}

func (e *evaluator) builtin(n *callNode, name string) interface{} {
	if _, ok := predicateBuiltins[name]; ok {
		return e.predicate(n, name)
	}
	a := e.argVals(n)
	arg := func(i int) interface{} {
		if i < len(a) {
			return a[i]
		}
		return nil
	}
	str := func(i int) string {
		s, _ := arg(i).(string)
		return s
	}
	switch name {
	case "len":
		v := arg(0)
		if s, ok := v.(string); ok {
			return len(s)
		}
		if m, ok := v.(map[string]interface{}); ok {
			return len(m)
		}
		if sl, ok := toSlice(v); ok {
			return len(sl)
		}
		e.fail(n, "invalid argument for len (type %v)", typeName(v))
	case "abs":
		v := arg(0)
		if isIntVal(v) {
			x := toInt(v)
			if x < 0 {
				x = -x
			}
			return x
		}
		return math.Abs(toFloat(v))
	case "ceil":
		return math.Ceil(toFloat(arg(0)))
	case "floor":
		return math.Floor(toFloat(arg(0)))
	case "round":
		return math.Round(toFloat(arg(0)))
	case "int":
		v := arg(0)
		if isNumVal(v) {
			return toInt(v)
		}
		if s, ok := v.(string); ok {
			var x int
			if _, err := fmt.Sscanf(s, "%d", &x); err == nil && fmt.Sprint(x) == strings.TrimSpace(s) {
				return x
			}
		}
		e.fail(n, "invalid operation: int(%v)", v)
	case "float":
		v := arg(0)
		if isNumVal(v) {
			return toFloat(v)
		}
		if s, ok := v.(string); ok {
			var x float64
			if _, err := fmt.Sscanf(s, "%g", &x); err == nil {
				return x
			}
		}
		e.fail(n, "invalid operation: float(%v)", v)
	case "string":
		return fmt.Sprint(arg(0))
	case "trim":
		if len(a) > 1 {
			return strings.Trim(str(0), str(1))
		}
		return strings.TrimSpace(str(0))
	case "trimPrefix":
		p := " "
		if len(a) > 1 {
			p = str(1)
		}
		return strings.TrimPrefix(str(0), p)
	case "trimSuffix":
		p := " "
		if len(a) > 1 {
			p = str(1)
		}
		return strings.TrimSuffix(str(0), p)
	case "upper":
		return strings.ToUpper(str(0))
	case "lower":
		return strings.ToLower(str(0))
	case "split":
		var parts []string
		if len(a) > 2 {
			parts = strings.SplitN(str(0), str(1), toInt(arg(2)))
		} else {
			parts = strings.Split(str(0), str(1))
		}
		out := make([]interface{}, len(parts))
		for i, p := range parts {
			out[i] = p
		}
		return out
	case "splitAfter":
		parts := strings.SplitAfter(str(0), str(1))
		out := make([]interface{}, len(parts))
		for i, p := range parts {
			out[i] = p
		}
		return out
	case "replace":
		return strings.ReplaceAll(str(0), str(1), str(2))
	case "repeat":
		c := toInt(arg(1))
		if c < 0 {
			e.fail(n, "invalid argument for repeat (count must be non-negative)")
		}
		return strings.Repeat(str(0), c)
	case "join":
		sl, _ := toSlice(arg(0))
		sep := ""
		if len(a) > 1 {
			sep = str(1)
		}
		parts := make([]string, len(sl))
		for i, x := range sl {
			s, ok := x.(string)
			if !ok {
				e.fail(n, "invalid argument for join (type %v)", typeName(x))
			}
			parts[i] = s
		}
		return strings.Join(parts, sep)
	case "indexOf":
		return strings.Index(str(0), str(1))
	case "lastIndexOf":
		return strings.LastIndex(str(0), str(1))
	case "hasPrefix":
		return strings.HasPrefix(str(0), str(1))
	case "hasSuffix":
		return strings.HasSuffix(str(0), str(1))
	case "max", "min":
		vals := a
		if len(a) == 1 {
			if sl, ok := toSlice(a[0]); ok {
				vals = sl
			}
		}
		if len(vals) == 0 {
			return nil
		}
		best := vals[0]
		for _, v := range vals[1:] {
			if (name == "max" && toFloat(v) > toFloat(best)) || (name == "min" && toFloat(v) < toFloat(best)) {
				best = v
			}
		}
		return best
	case "sum":
		sl, _ := toSlice(arg(0))
		allInt := true
		var fi int
		var ff float64
		for _, v := range sl {
			if isIntVal(v) {
				fi += toInt(v)
			} else {
				allInt = false
			}
			ff += toFloat(v)
		}
		if allInt {
			return fi
		}
		return ff
	case "mean":
		sl, _ := toSlice(arg(0))
		if len(sl) == 0 {
			return 0.0
		}
		var s float64
		for _, v := range sl {
			s += toFloat(v)
		}
		return s / float64(len(sl))
	case "median":
		sl, _ := toSlice(arg(0))
		if len(sl) == 0 {
			return 0.0
		}
		fs := make([]float64, len(sl))
		for i, v := range sl {
			fs[i] = toFloat(v)
		}
		sort.Float64s(fs)
		if len(fs)%2 == 0 {
			return (fs[len(fs)/2-1] + fs[len(fs)/2]) / 2
		}
		return fs[len(fs)/2]
	case "first":
		sl, _ := toSlice(arg(0))
		if len(sl) == 0 {
			return nil
		}
		return sl[0]
	case "last":
		sl, _ := toSlice(arg(0))
		if len(sl) == 0 {
			return nil
		}
		return sl[len(sl)-1]
	case "take":
		sl, _ := toSlice(arg(0))
		k := toInt(arg(1))
		if k > len(sl) {
			k = len(sl)
		}
		if k < 0 {
			k = 0
		}
		return sl[:k]
	case "keys", "values":
		m, _ := arg(0).(map[string]interface{})
		ks := make([]string, 0, len(m))
		for k := range m {
			ks = append(ks, k)
		}
		sort.Strings(ks)
		out := make([]interface{}, len(ks))
		for i, k := range ks {
			if name == "keys" {
				out[i] = k
			} else {
				out[i] = m[k]
			}
		}
		return out
	case "toJSON":
		b, err := json.MarshalIndent(arg(0), "", "  ")
		if err != nil {
