			e.fail(n, "cannot iterate over %v", typeName(coll))
		}
	}
	run := func(v interface{}) interface{} {
		return e.withPtr(v, func() interface{} { return e.eval(body) })
	}
	switch name {
	case "all":
		for _, v := range sl {
			if !truthy(run(v)) {
				return false
			}
		}
		return true
	case "any":
		for _, v := range sl {
			if truthy(run(v)) {
				return true
			}
		}
		return false
	case "none":
		for _, v := range sl {
			if truthy(run(v)) {
				return false
			}
		}
		return true
	case "one":
		c := 0
		for _, v := range sl {
			if truthy(run(v)) {
				c++
			}
		}
		return c == 1
	case "filter":
		out := []interface{}{}
		for _, v := range sl {
			if truthy(run(v)) {
				out = append(out, v)
			}
		}
		return out
	case "map":
		out := make([]interface{}, 0, len(sl))
		for _, v := range sl {
			out = append(out, run(v))
		}
		return out
	case "count":
		c := 0
		for _, v := range sl {
			if truthy(run(v)) {
				c++
			}
		}
		return c
	case "sum":
		allInt := true
		var si int
		var sf float64
		for _, v := range sl {
			r := run(v)
			if isIntVal(r) {
				si += toInt(r)
			} else {
				allInt = false
			}
			sf += toFloat(r)
		}
		if allInt {
			return si
		}
		return sf
	case "find":
		for _, v := range sl {
			if truthy(run(v)) {
				return v
			}
		}
		return nil
	case "findIndex":
		for i, v := range sl {
			if truthy(run(v)) {
				return i
			}
		}
		return -1
	case "findLast":
		for i := len(sl) - 1; i >= 0; i-- {
			if truthy(run(sl[i])) {
				return sl[i]
			}
		}
		return nil
	case "findLastIndex":
		for i := len(sl) - 1; i >= 0; i-- {
			if truthy(run(sl[i])) {
				return i
			}
		}
		return -1
	case "groupBy":
		out := map[string]interface{}{}
		for _, v := range sl {
			k := fmt.Sprint(run(v))
			lst, _ := out[k].([]interface{})
			out[k] = append(lst, v)
		}
		return out
	case "sortBy":
		out := append([]interface{}{}, sl...)
		keys := make([]interface{}, len(out))
		for i, v := range out {
			keys[i] = run(v)
		}
		idx := make([]int, len(out))
		for i := range idx {
			idx[i] = i
		}
		desc := len(n.args) > 2 && fmt.Sprint(e.eval(n.args[2])) == "desc"
		sort.SliceStable(idx, func(i, j int) bool {
			x, y := keys[idx[i]], keys[idx[j]]
			var less bool
			if isString(x) && isString(y) {
				less = x.(string) < y.(string)
				if desc {
					less = x.(string) > y.(string)
				}
			} else {
				less = toFloat(x) < toFloat(y)
				if desc {
					less = toFloat(x) > toFloat(y)
				}
			}
			return less
		})
		res := make([]interface{}, len(out))
		for i, k := range idx {
			res[i] = out[k]
		}
		return res
	case "reduce":
		var acc interface{}
		start := 0
		if len(n.args) > 2 {
			acc = e.eval(n.args[2])
		} else if len(sl) > 0 {
			acc = sl[0]
			start = 1
		}
		for i := start; i < len(sl); i++ {
			v := sl[i]
			old, had := e.vars["#acc"]
			e.vars["#acc"] = acc
			acc = e.withPtr(v, func() interface{} {
				e.vars["acc"] = acc
				return e.eval(body)
			})
			if had {
				e.vars["#acc"] = old
			}
		}
		delete(e.vars, "acc")
		return acc
	}
	return nil
}
