	"bitushr":     {{params: []ptype{pInt, pInt}}},
	"type":        {{params: []ptype{{xUnknown, "interface {}"}}}},
}

func ptypeAssignable(arg xt, p ptype) bool {
	if arg == xUnknown || p.t == xUnknown {
		return true
	}
	if p.name == "[]string" {
		return arg == xArray
	}
	if arg == xNil {
		return p.t == xArray || p.t == xMap
	}
	return arg == p.t
}

// checkBuiltin returns (handled, return type).
func (c *checker) checkBuiltin(n *callNode, name string, argTypes []xt) (bool, xt) {
	if ovs, ok := typedBuiltins[name]; ok {
		var lastErr func()
		for _, ov := range ovs {
			ok := true
			if !ov.variadic && len(argTypes) > len(ov.params) {
				lastErr = func() { c.fail(n, "too many arguments to call %v", name) }
				ok = false
			} else if len(argTypes) < len(ov.params) {
				lastErr = func() { c.fail(n, "not enough arguments to call %v", name) }
				ok = false
			} else {
				for i, at := range argTypes {
					if i < len(ov.params) && !ptypeAssignable(at, ov.params[i]) {
						i, at := i, at
						p := ov.params[i]
						lastErr = func() {
							c.fail(n.args[i], "cannot use %v as argument (type %v) to call %v ", at, p.name, name)
						}
						ok = false
						break
					}
				}
			}
			if ok {
				return true, builtinRet[name]
			}
		}
		if lastErr != nil {
			lastErr()
		}
		return true, xUnknown
	}
	arity := func(exp int) bool {
		if len(argTypes) != exp {
			c.fail(n, "invalid number of arguments (expected %d, got %d)", exp, len(argTypes))
			return false
		}
		return true
	}
	first := xUnknown
	if len(argTypes) > 0 {
		first = argTypes[0]
	}
	switch name {
	case "len":
		if !arity(1) {
			return true, xUnknown
		}
		if first != xUnknown && first != xArray && first != xMap && first != xString {
			c.fail(n, "invalid argument for len (type %v)", first)
		}
		return true, xInt
	case "abs", "ceil", "floor", "round":
		if !arity(1) {
			return true, xUnknown
		}
		if first != xUnknown && !isNum(first) {
			c.fail(n, "invalid argument for %v (type %v)", name, first)
		}
		if name == "abs" && isNum(first) {
			return true, first
		}
		if name == "abs" {
			return true, xUnknown
		}
		return true, xFloat
	case "int", "float":
		if !arity(1) {
			return true, xUnknown
		}
		if first != xUnknown && !isNum(first) && first != xString {
			c.fail(n, "invalid argument for %v (type %v)", name, first)
		}
		if name == "int" {
			return true, xInt
		}
		return true, xFloat
	case "max", "min":
		if len(argTypes) == 0 {
			c.fail(n, "not enough arguments to call %v", name)
			return true, xUnknown
		}
		for _, t := range argTypes {
			if t != xUnknown && !isNum(t) && !(len(argTypes) == 1 && t == xArray) {
				c.fail(n, "invalid argument for %v (type %v)", name, t)
				return true, xUnknown
			}
		}
		return true, xUnknown
	case "first", "last":
		if !arity(1) {
			return true, xUnknown
		}
		if first != xUnknown && first != xArray {
			c.fail(n, "cannot get %v element from %v", name, first)
		}
		return true, xUnknown
	case "keys", "values":
		if !arity(1) {
			return true, xUnknown
		}
		if first != xUnknown && first != xMap {
			c.fail(n, "cannot get %v from %v", name, first)
		}
		return true, xArray
	case "toPairs":
		if !arity(1) {
			return true, xUnknown
		}
		if first != xUnknown && first != xMap {
			c.fail(n, "cannot transform %v to pairs", first)
		}
		return true, xArray
	case "now":
		arity(0)
		return true, xTime
	case "take", "get":
		arity(2)
		if name == "take" {
			return true, xArray
		}
		return true, xUnknown
	}
	return false, xUnknown
}
